window.GRAM_CORE = [

/* ============ 1 · alphabet ============ */
{id:'alphabet',ic:'🔤',lv:1,sk:'Beginner',
 title:{en:'The German alphabet & its sounds',fa:'الفبای آلمانی و صداهایش'},
 sub:{en:'26 letters + ä ö ü ß — and how each one really sounds',fa:'۲۶ حرف + ä ö ü ß — و تلفظ واقعی هرکدام'},
 blocks:[
  {type:'text',md:{en:'German uses the same 26 Latin letters as English, plus <b>ä, ö, ü</b> (the <i>Umlaute</i>) and <b>ß</b> (the <i>Eszett</i>). But the important news is not the extra letters — it is that German spelling is <b>honest</b>. Unlike English, a German letter almost always makes the same sound every time. Learn the sound of each letter once and you can read aloud a word you have never seen, correctly, on the first try.',
        fa:'آلمانی همان ۲۶ حرف لاتین انگلیسی را دارد، به‌علاوهٔ <b>ä، ö، ü</b> (اوملاوت) و <b>ß</b> (اِس‌تسِت). اما خبر مهم حروف اضافه نیست — خبر مهم این است که املای آلمانی <b>صادق</b> است. برخلاف انگلیسی، هر حرف تقریباً همیشه یک صدا می‌دهد. وقتی صدای هر حرف را یاد بگیری، می‌توانی واژه‌ای را که هرگز ندیده‌ای، از همان بار اول درست بخوانی.'}},
  {type:'table',head:['Letter','Sounds like','German word'],rows:[
   ['*w','English *v','*Wasser, Wein, wo'],
   ['*v','English *f','*Vater, vier, von'],
   ['*z','English *ts','*zehn, Zeit, Zimmer'],
   ['*j','English *y','*ja, Jahr, jung'],
   ['*s','English *z before a vowel','*sagen, Sonne, lesen'],
   ['*ß','a sharp *ss, never z','*Straße, heiß, groß'],
   ['*sch','English *sh','*Schule, schön, Tisch'],
   ['*ch','breathy — as in Scottish „loch“','*Buch, acht, auch'],
   ['*ei','English *eye','*ein, nein, Wein'],
   ['*ie','a long *ee','*Bier, vier, Wien'],
   ['*eu / äu','English *oy','*neun, Leute, Häuser'],
   ['*-er at the end','a soft *-a','*Mutter, Vater, besser']],
   cap:{en:'These twelve rows cause nearly every beginner mispronunciation.',
        fa:'همین دوازده ردیف عامل تقریباً همهٔ غلط‌خوانی‌های آغازین است.'}},
  {type:'rule',md:{en:'<b>ei</b> and <b>ie</b> are the one pair worth drilling to reflex, because they look alike and sound nothing alike. The trick: <b>pronounce the second letter</b>. <b>ei</b> → say the letter „i“ (= eye). <b>ie</b> → say the letter „e“ (= ee).<br>So <b class="deword">Wein</b> = „vine“ and <b class="deword">Wien</b> = „veen“.',
        fa:'<b>ei</b> و <b>ie</b> تنها جفتی هستند که ارزش تمرین تا حد واکنش خودکار را دارند، چون شبیه هم‌اند و هیچ شباهت صوتی ندارند. ترفند: <b>حرف دوم را تلفظ کن</b>. <b>ei</b> → «آی». <b>ie</b> → «ای» کشیده.'}},
  {type:'contrast',cols:[
   {t:'The Umlaute: ä ö ü',md:{en:'<b>ä</b> = the <i>e</i> in „bed“ — <b class="deword">Bär, spät, Mädchen</b>.<br><b>ö</b> = say „e“, then round your lips — <b class="deword">schön, hören, können</b>.<br><b>ü</b> = say „ee“, then round your lips — <b class="deword">Tür, über, müde</b>.<br>Your tongue stays where it is for the vowel; only the lips move.'}},
   {t:'Why they matter',md:{en:'The Umlaut is not decoration — it changes the word.<br><b class="deword">schon</b> = already, <b class="deword">schön</b> = beautiful.<br><b class="deword">Mutter</b> = mother, <b class="deword">Mütter</b> = mothers.<br>Drop the two dots and you have said something else, so write them.'}}]},
  {type:'examples',items:[
   {de:'Wie heißen Sie?',en:'What is your name? (formal) — „vee HY-ssen zee“',say:'Wie heißen Sie?'},
   {de:'Ich wohne in Wien.',en:'I live in Vienna. — „veen“, not „wine“',say:'Ich wohne in Wien.'},
   {de:'Vier Gläser Wasser, bitte.',en:'Four glasses of water, please. — „feer“, „VAS-ser“',say:'Vier Gläser Wasser, bitte.'},
   {de:'Die Straße ist sehr schön.',en:'The street is very beautiful.',say:'Die Straße ist sehr schön.'},
   {de:'Zwei Zimmer, zehn Euro.',en:'Two rooms, ten euros. — z = ts',say:'Zwei Zimmer, zehn Euro.'},
   {de:'Ich spreche ein bisschen Deutsch.',en:'I speak a little German.',say:'Ich spreche ein bisschen Deutsch.'}]},
  {type:'warn',md:{en:'The three sounds English speakers get wrong for years:<br>1. <b>w</b> is a <i>v</i>. „Wein“ is <s>ween</s> ✗ and <s>wine</s> ✗ — it is <b>vine</b>. „Wasser“ starts like „vast“.<br>2. <b>v</b> is an <i>f</i>. „Vater“ is <s>VAH-ter with a v</s> ✗ — it is <b>FAH-ter</b>.<br>3. <b>z</b> is <i>ts</i>, never English z. „zehn“ = <b>tsayn</b>, „Zeit“ = <b>tsite</b>.<br>Say the pair „Wein – vier“ aloud ten times: <b>v</b>ine – <b>f</b>eer. That one drill fixes most of it.',
        fa:'سه صدایی که انگلیسی‌زبان‌ها سال‌ها اشتباه می‌گویند: ۱) <b>w</b> صدای «و» است، نه «w» انگلیسی. ۲) <b>v</b> صدای «ف» است. ۳) <b>z</b> صدای «تس» است، هرگز «ز».'}},
  {type:'tip',md:{en:'Keyboard trouble? If you cannot type ä ö ü ß, write <b>ae oe ue ss</b> instead — every German reads that without blinking (<i>Strasse, schoen, Tuer</i>). What you must not do is simply drop the dots: „schon“ and „schön“ are two different words.',
        fa:'مشکل صفحه‌کلید؟ اگر نمی‌توانی ä ö ü ß تایپ کنی، به‌جایشان <b>ae oe ue ss</b> بنویس — هر آلمانی‌زبانی می‌فهمد. اما نقطه‌ها را حذف نکن: «schon» و «schön» دو واژهٔ متفاوت‌اند.'}},
  {type:'quiz',q:{en:'Which German word rhymes with English „mine“?',fa:'کدام واژهٔ آلمانی با «mine» انگلیسی هم‌قافیه است؟'},
   a:'Wein',o:['Wien','wie','wir'],
   ex:{en:'<b>ei</b> → pronounce the second letter, „i“ = eye. So <b>Wein</b> = „vine“. The other three all contain <b>ie</b> or <b>i</b> and come out as „ee“: Wien = veen, wie = vee, wir = veer.',
       fa:'در <b>ei</b> حرف دوم را تلفظ می‌کنیم، پس <b>Wein</b> مثل «vine» است. سه گزینهٔ دیگر صدای «ای» کشیده دارند.'}}
 ]},

/* ============ 2 · greetings ============ */
{id:'greetings',ic:'👋',lv:1,sk:'Beginner',
 title:{en:'Greetings & politeness',fa:'سلام و ادب'},
 sub:{en:'Hello, thanks, sorry — and the du/Sie decision',fa:'سلام، تشکر، عذرخواهی — و انتخاب میان du و Sie'},
 blocks:[
  {type:'text',md:{en:'These are the words you will use on day one, and they carry more weight in German than in English. The reason is <b>du</b> and <b>Sie</b>: German forces you to choose, with every single sentence, whether you are speaking to this person as a friend or as a stranger. Grammar mistakes are forgiven instantly. Calling your landlord <b>du</b> is the one thing that actually lands badly.',
        fa:'این‌ها واژه‌هایی هستند که از روز اول به کارت می‌آیند، و در آلمانی وزن بیشتری از انگلیسی دارند. دلیلش <b>du</b> و <b>Sie</b> است: آلمانی در هر جمله مجبورت می‌کند انتخاب کنی که با این شخص دوستانه حرف می‌زنی یا رسمی. خطای دستوری فوراً بخشیده می‌شود؛ اما «du» گفتن به صاحب‌خانه‌ات واقعاً بد می‌نشیند.'}},
  {type:'table',head:['When','Greeting','Leaving'],rows:[
   ['before ~11:00','*Guten Morgen','Tschüss / Auf Wiedersehen'],
   ['the whole day','*Guten Tag','Auf Wiedersehen'],
   ['from ~18:00','*Guten Abend','Guten Abend / Tschüss'],
   ['going to bed','—','*Gute Nacht'],
   ['friends, any time','*Hallo / Hi','*Tschüss / Bis bald'],
   ['north Germany','*Moin','Tschüss'],
   ['Bavaria, Austria','*Grüß Gott / Servus','*Servus / Auf Wiederschauen'],
   ['phone','*Hallo? + your surname','*Auf Wiederhören']],
   cap:{en:'„Guten Tag“ is never wrong. When in doubt, use it.',
        fa:'«Guten Tag» هرگز غلط نیست. در تردید، همین را بگو.'}},
  {type:'contrast',cols:[
   {t:'du — informal',md:{en:'Friends, family, children, students, colleagues your own age, anyone who offers it first.<br>Verb: „Wie geht es <b>dir</b>?“ · „Wo wohnst <b>du</b>?“<br>You use the first name: „Hallo Anna!“'}},
   {t:'Sie — formal',md:{en:'Strangers, shop and office staff, doctors, teachers, landlords, anyone older you do not know, every official letter.<br>Verb: „Wie geht es <b>Ihnen</b>?“ · „Wo wohnen <b>Sie</b>?“<br>You use Herr/Frau + surname: „Guten Tag, Frau Weber.“'}}]},
  {type:'examples',items:[
   {de:'Guten Tag, ich heiße Sara.',en:'Hello, my name is Sara.',say:'Guten Tag, ich heiße Sara.'},
   {de:'Entschuldigung, wo ist der Bahnhof?',en:'Excuse me, where is the station?',say:'Entschuldigung, wo ist der Bahnhof?'},
   {de:'Vielen Dank! — Bitte schön.',en:'Many thanks! — You are welcome.',say:'Vielen Dank! Bitte schön.'},
   {de:'Wie geht es Ihnen? — Danke, gut.',en:'How are you? (formal) — Fine, thanks.',say:'Wie geht es Ihnen? Danke, gut.'},
   {de:'Tut mir leid, ich habe das nicht verstanden.',en:'I am sorry, I did not understand that.',say:'Tut mir leid, ich habe das nicht verstanden.'},
   {de:'Tschüss, bis morgen!',en:'Bye, see you tomorrow!',say:'Tschüss, bis morgen!'}]},
  {type:'dialog',lines:[
   {who:'A',de:'Guten Morgen! Was darf es sein?',en:'Good morning! What can I get you?'},
   {who:'B',de:'Guten Morgen. Zwei Brötchen, bitte.',en:'Good morning. Two rolls, please.'},
   {who:'A',de:'Sonst noch etwas?',en:'Anything else?'},
   {who:'B',de:'Nein, danke. Das ist alles.',en:'No thanks. That is all.'},
   {who:'A',de:'Das macht zwei Euro vierzig.',en:'That comes to two euros forty.'},
   {who:'B',de:'Bitte schön. — Danke, tschüss!',en:'Here you go. — Thanks, bye!'}]},
  {type:'warn',md:{en:'Three mistakes English speakers make on day one:<br>1. <b>„Gute Nacht“ is a goodbye, not a greeting.</b> It means „sleep well“. Walking into an evening party with „Gute Nacht!“ tells everyone you are leaving. Say <b>Guten Abend</b>.<br>2. <b>Do not use „du“ with staff and officials.</b> In a shop, at the doctor, at the Bürgeramt: <b>Sie</b>. Wait until the other person says „Wir können uns duzen“ — then switch.<br>3. <b>„Wie geht es Ihnen?“ is answered, not ignored.</b> Unlike English „How are you?“ it is a real question. One short honest line is the norm: „Danke, gut. Und Ihnen?“',
        fa:'سه خطای روز اول: ۱) «Gute Nacht» خداحافظی است، نه سلام — برای شب از «Guten Abend» استفاده کن. ۲) با کارمند، پزشک و اداره «Sie» بگو، نه «du». ۳) «Wie geht es Ihnen؟» پرسش واقعی است و پاسخ کوتاه می‌خواهد: «Danke, gut. Und Ihnen؟»'}},
  {type:'tip',md:{en:'<b>Bitte</b> is the hardest-working word in German. It means „please“ („Einen Kaffee, <b>bitte</b>“), „you are welcome“ (the reply to Danke), „here you go“ (handing something over) and „pardon?“ (said with a rising tone: „Bitte?“). Four jobs, one word — and it makes almost any request polite.',
        fa:'<b>bitte</b> پرکارترین واژهٔ آلمانی است: «لطفاً»، «خواهش می‌کنم»، «بفرمایید» و با آهنگ پرسشی «ببخشید؟». چهار کار با یک واژه — و تقریباً هر درخواستی را مؤدب می‌کند.'}},
  {type:'quiz',q:{en:'Which of these is a goodbye, not a greeting?',fa:'کدام‌یک خداحافظی است، نه سلام؟'},
   a:'Gute Nacht',o:['Guten Morgen','Guten Tag','Guten Abend'],
   ex:{en:'<b>Gute Nacht</b> is said when someone is going to bed or leaving late — it is „good night“ in the sleep-well sense. The evening <i>greeting</i> is <b>Guten Abend</b>. Notice the ending too: <i>Gute</i> Nacht (feminine), but <i>Guten</i> Morgen/Tag/Abend (masculine).',
       fa:'<b>Gute Nacht</b> هنگام خواب یا رفتن در پایان شب گفته می‌شود. سلامِ شب <b>Guten Abend</b> است. به پایانه هم دقت کن: Gute Nacht (مؤنث) اما Guten Morgen/Tag/Abend (مذکر).'}}
 ]},

/* ============ 3 · numbers ============ */
{id:'numbers',ic:'🔢',lv:1,sk:'Numbers',
 title:{en:'Numbers 0–100',fa:'شمارش ۰ تا ۱۰۰'},
 sub:{en:'Counting — and the famous backwards twenties',fa:'شمارش — و آن دهگان‌های برعکس معروف'},
 blocks:[
  {type:'text',md:{en:'Learn <b>0–12</b> by heart; there is no pattern to help you. From <b>13–19</b> German simply glues the unit onto <b>-zehn</b> („-teen“): <i>drei</i> + <i>zehn</i> = <b>dreizehn</b>. The tens all end in <b>-zig</b>. And then comes the part that trips up every learner: from 21 upwards, German says the <b>unit first</b>.',
        fa:'<b>۰ تا ۱۲</b> را حفظ کن؛ الگویی ندارد. از <b>۱۳ تا ۱۹</b> آلمانی یکان را به <b>-zehn</b> می‌چسباند: <i>drei</i> + <i>zehn</i> = <b>dreizehn</b>. دهگان‌ها همه به <b>-zig</b> ختم می‌شوند. و بعد همان بخشی می‌آید که هر زبان‌آموزی را گیر می‌اندازد: از ۲۱ به بالا، آلمانی ابتدا <b>یکان</b> را می‌گوید.'}},
  {type:'table',head:['#','Deutsch','#','Deutsch'],rows:[
   ['0','null','11','elf'],
   ['1','eins','12','zwölf'],
   ['2','zwei','13','dreizehn'],
   ['3','drei','14','vierzehn'],
   ['4','vier','15','fünfzehn'],
   ['5','fünf','16','*sechzehn'],
   ['6','sechs','17','*siebzehn'],
   ['7','sieben','18','achtzehn'],
   ['8','acht','19','neunzehn'],
   ['9','neun','20','zwanzig'],
   ['10','zehn','',''],
   ],
   cap:{en:'16 and 17 lose a letter: sechzehn, siebzehn — not „sechszehn“, not „siebenzehn“.',
        fa:'۱۶ و ۱۷ یک حرف را از دست می‌دهند: sechzehn، siebzehn.'}},
  {type:'rule',md:{en:'From 21 to 99, German reads the number <b>backwards</b> and writes it as <b>one single word</b>:<br><b>21</b> = ein<b>und</b>zwanzig — literally „one-and-twenty“<br><b>47</b> = sieben<b>und</b>vierzig — „seven-and-forty“<br><b>99</b> = neun<b>und</b>neunzig<br>No spaces, no hyphens. And note that <i>eins</i> loses its -s inside the word: ein<b>und</b>dreißig, not „einsunddreißig“.',
        fa:'از ۲۱ تا ۹۹ آلمانی عدد را <b>برعکس</b> می‌خواند و همه را <b>یک واژه</b> می‌نویسد: <b>۲۱</b> = einundzwanzig («یک‌وبیست»)، <b>۴۷</b> = siebenundvierzig. بدون فاصله. و <i>eins</i> داخل واژه، s خود را از دست می‌دهد: einunddreißig.'}},
  {type:'table',head:['#','Deutsch','#','Deutsch'],rows:[
   ['20','zwanzig','70','*siebzig'],
   ['30','*dreißig','80','achtzig'],
   ['40','vierzig','90','neunzig'],
   ['50','fünfzig','100','(ein)hundert'],
   ['60','*sechzig','1000','(ein)tausend']],
   cap:{en:'30 is the only ten spelt with ß: dreißig, never „dreizig“.',
        fa:'۳۰ تنها دهگانی است که با ß نوشته می‌شود: dreißig.'}},
  {type:'steps',items:[
   {en:'Hear the whole number to the <b>end</b> before you write anything. The last part is the tens.',fa:'عدد را تا <b>آخر</b> بشنو و بعد بنویس. بخش آخر، دهگان است.'},
   {en:'Find the <b>und</b>. What comes <i>after</i> it is the tens digit; what comes <i>before</i> it is the unit.',fa:'دنبال <b>und</b> بگرد. آنچه <i>پس</i> از آن است دهگان است و آنچه <i>پیش</i> از آن است یکان.'},
   {en:'Write the tens first, then the unit: „sieben<b>und</b>vierzig“ → 4, then 7 → <b>47</b>.',fa:'نخست دهگان را بنویس، بعد یکان: «siebenundvierzig» → ۴ و بعد ۷ → <b>۴۷</b>.'},
   {en:'No <b>und</b> at all? Then it is a round ten, a teen, or a single digit — no reversing needed.',fa:'اگر <b>und</b> نبود، عدد رُند، نوجوان یا یک‌رقمی است و برعکس‌کردن لازم نیست.'}]},
  {type:'examples',items:[
   {de:'Ich bin dreiundzwanzig Jahre alt.',en:'I am twenty-three years old.',say:'Ich bin dreiundzwanzig Jahre alt.'},
   {de:'Das kostet vierzehn Euro fünfzig.',en:'That costs fourteen euros fifty.',say:'Das kostet vierzehn Euro fünfzig.'},
   {de:'Ich wohne in der Hauptstraße siebenundzwanzig.',en:'I live at Hauptstraße twenty-seven.',say:'Ich wohne in der Hauptstraße siebenundzwanzig.'},
   {de:'Der Bus kommt um acht Uhr zweiundzwanzig.',en:'The bus comes at eight twenty-two.',say:'Der Bus kommt um acht Uhr zweiundzwanzig.'},
   {de:'Wir sind einundvierzig Leute im Kurs.',en:'There are forty-one of us in the course.',say:'Wir sind einundvierzig Leute im Kurs.'},
   {de:'Meine Nummer ist null eins sieben null, drei vier…',en:'My number is 0170 34… (digits read one by one)',say:'null eins sieben null, drei vier'}]},
  {type:'warn',md:{en:'The expensive mistake: <b>hearing 24 and writing 42</b>. „vierundzwanzig“ begins with <i>vier</i>, so the hand writes 4 first — and the 4 belongs at the <i>end</i>. This costs people money at tills and makes them miss trains. The fix is behavioural, not grammatical: <b>wait for the end of the word</b>, then write the second half first.<br>Also: say <b>eins</b> only when the number stands alone („Nummer eins“, „eins, zwei, drei“). Before a noun it becomes an article: „<b>ein</b> Buch“, „<b>eine</b> Frau“ — never „<s>eins Buch</s>“ ✗.',
        fa:'خطای پرهزینه: شنیدن ۲۴ و نوشتن ۴۲. «vierundzwanzig» با <i>vier</i> شروع می‌شود، پس دست اول ۴ را می‌نویسد — در حالی که ۴ جایش <i>آخر</i> است. چاره رفتاری است: <b>تا پایان واژه صبر کن</b>. و <b>eins</b> را فقط وقتی بگو که عدد تنها باشد؛ پیش از اسم به حرف تعریف تبدیل می‌شود: «ein Buch».'}},
  {type:'tip',md:{en:'Years have their own habit. Up to 1999 you say them in hundreds: <b>1999</b> = neunzehnhundertneunundneunzig, <b>1848</b> = achtzehnhundertachtundvierzig. From 2000 on you say them straight: <b>2024</b> = zweitausendvierundzwanzig. Phone numbers are read digit by digit — much easier than it sounds.',
        fa:'سال‌ها عادت خودشان را دارند. تا ۱۹۹۹ به‌صورت صدگانی: <b>۱۹۹۹</b> = neunzehnhundertneunundneunzig. از ۲۰۰۰ به بعد مستقیم: <b>۲۰۲۴</b> = zweitausendvierundzwanzig. شمارهٔ تلفن را رقم‌به‌رقم می‌خوانند.'}},
  {type:'quiz',q:{en:'A waiter says „siebenundvierzig Euro“. How much is the bill?',fa:'گارسون می‌گوید «siebenundvierzig Euro». صورت‌حساب چقدر است؟'},
   a:'47',o:['74','17','77'],
   ex:{en:'Find the <b>und</b>: <i>sieben</i>-und-<i>vierzig</i>. After the „und“ comes the tens (vierzig = 40), before it the unit (sieben = 7) → <b>47</b>. Writing 74 is exactly the trap: that would be „vierundsiebzig“.',
       fa:'دنبال <b>und</b> برو: sieben-und-vierzig. پس از «und» دهگان است (vierzig = ۴۰) و پیش از آن یکان (sieben = ۷) → <b>۴۷</b>. نوشتن ۷۴ همان دام است؛ ۷۴ می‌شود «vierundsiebzig».'}}
 ]},

/* ============ 4 · pronouns ============ */
{id:'pronouns',ic:'🙋',lv:2,sk:'Verbs',
 title:{en:'Personal pronouns',fa:'ضمایر شخصی'},
 sub:{en:'ich, du, Sie — and the mich/mir split',fa:'ich، du، Sie — و تفاوت mich و mir'},
 blocks:[
  {type:'text',md:{en:'Pronouns stand in for people and things so you do not repeat the noun. English does this too, and English pronouns already change shape: <i>I → me</i>, <i>he → him</i>, <i>they → them</i>. German does the same thing, only it splits the object form in <b>two</b>: one for the thing acted on (<i>mich</i>) and one for the person the action reaches (<i>mir</i>). That single extra distinction is the whole difficulty — and once you see it as „me“ vs „to me“, it stops being mysterious.',
        fa:'ضمیر جای شخص یا چیز می‌نشیند تا اسم را تکرار نکنی. انگلیسی هم همین کار را می‌کند و ضمایرش شکل عوض می‌کنند: <i>I → me</i>، <i>he → him</i>. آلمانی همان کار را می‌کند، فقط شکل مفعولی را به <b>دو</b> بخش می‌کند: یکی برای چیزی که روی آن عمل می‌شود (<i>mich</i>) و یکی برای کسی که عمل به او می‌رسد (<i>mir</i>). همین یک تفاوت، تمام دشواری است — و وقتی آن را «me» در برابر «to me» ببینی، دیگر معما نیست.'}},
  {type:'table',head:['Deutsch','English','فارسی'],rows:[
   ['ich','I','من'],
   ['du','you (one friend)','تو'],
   ['er','he / it (der-noun)','او (مرد)'],
   ['sie','she / it (die-noun)','او (زن)'],
   ['es','it (das-noun)','آن'],
   ['wir','we','ما'],
   ['ihr','you (several friends)','شما (جمع، خودی)'],
   ['sie','they','آن‌ها'],
   ['Sie','you (formal, always capital)','شما (رسمی)']],
   cap:{en:'German has three „you“: du (one friend), ihr (several friends), Sie (formal).',
        fa:'آلمانی سه «شما» دارد: du، ihr، Sie.'}},
  {type:'table',head:['Nominativ (subject)','Akkusativ (object)','Dativ (receiver)'],rows:[
   ['ich','*mich','*mir'],
   ['du','*dich','*dir'],
   ['er','*ihn','*ihm'],
   ['sie (she)','sie','*ihr'],
   ['es','es','*ihm'],
   ['wir','*uns','uns'],
   ['ihr','*euch','euch'],
   ['sie (they)','sie','*ihnen'],
   ['Sie (formal)','Sie','*Ihnen']],
   cap:{en:'Three columns, and the middle one is the one English already has. Only mir/dir/ihm/ihr/ihnen are genuinely new.',
        fa:'سه ستون؛ ستون میانی همان چیزی است که انگلیسی هم دارد. فقط mir/dir/ihm/ihr/ihnen تازه‌اند.'}},
  {type:'contrast',cols:[
   {t:'Akkusativ — the thing acted on',md:{en:'Ask <b>wen?</b> („whom / what?“)<br>„Ich sehe <b>ihn</b>.“ — I see him.<br>„Ruf <b>mich</b> an!“ — Call me.<br>„Ich liebe <b>dich</b>.“ — I love you.<br>The pronoun is directly hit by the verb.'}},
   {t:'Dativ — the person it reaches',md:{en:'Ask <b>wem?</b> („to whom?“)<br>„Ich helfe <b>ihm</b>.“ — I help him.<br>„Gib <b>mir</b> das Buch.“ — Give me the book.<br>„Wie geht es <b>dir</b>?“ — How are you?<br>The pronoun receives, benefits, or is addressed.'}}]},
  {type:'examples',items:[
   {de:'Kannst du mir bitte helfen?',en:'Can you help me, please? (helfen → Dativ)',say:'Kannst du mir bitte helfen?'},
   {de:'Ich rufe dich morgen an.',en:'I will call you tomorrow. (anrufen → Akkusativ)',say:'Ich rufe dich morgen an.'},
   {de:'Das Buch gehört ihm.',en:'The book belongs to him.',say:'Das Buch gehört ihm.'},
   {de:'Ich sehe ihn jeden Morgen im Bus.',en:'I see him every morning on the bus.',say:'Ich sehe ihn jeden Morgen im Bus.'},
   {de:'Wie geht es dir? — Danke, mir geht es gut.',en:'How are you? — I am fine, thanks.',say:'Wie geht es dir? Danke, mir geht es gut.'},
   {de:'Können Sie mir sagen, wo der Bahnhof ist?',en:'Can you tell me where the station is?',say:'Können Sie mir sagen, wo der Bahnhof ist?'}]},
  {type:'warn',md:{en:'English has <b>one</b> word „me“ for both German forms, so it gives you no warning at all. That produces the single most common pronoun error:<br>„<s>Kannst du mich helfen?</s>“ ✗ → „Kannst du <b>mir</b> helfen?“ ✓<br><b>helfen, danken, antworten, gehören, gefallen, passen</b> all take <b>Dativ</b>, even though their English translations look like plain objects.<br>Second trap: <b>sie</b> has three meanings. „sie kommt“ = she, „sie kommen“ = they, „Sie kommen“ = you (formal). Let the <i>verb ending</i> and the <i>capital letter</i> decide — and in writing, always capitalise the formal <b>Sie</b>, or you have just called your boss „she“.',
        fa:'انگلیسی برای هر دو شکل آلمانی یک واژه دارد («me») و هیچ هشداری نمی‌دهد. نتیجه، رایج‌ترین خطای ضمیر است: «Kannst du mich helfen؟» ✗ → «Kannst du <b>mir</b> helfen؟» ✓. فعل‌های helfen، danken، antworten، gehören، gefallen و passen همه <b>داتیو</b> می‌گیرند. دام دوم: <b>sie</b> سه معنا دارد؛ پایانهٔ فعل و حرف بزرگ تعیین می‌کنند.'}},
  {type:'tip',md:{en:'Learn the masculine triple as a chant — <b>er · ihn · ihm</b> — and your own triple — <b>ich · mich · mir</b>. Those six words cover the great majority of real pronoun mistakes, because the feminine, neuter and plural object forms (<i>sie, es, uns, euch</i>) barely change at all.',
        fa:'سه‌گانهٔ مذکر را مثل یک ذکر یاد بگیر — <b>er · ihn · ihm</b> — و سه‌گانهٔ خودت را — <b>ich · mich · mir</b>. همین شش واژه بیشترِ خطاهای واقعی را پوشش می‌دهد، چون شکل‌های مؤنث، خنثی و جمع تقریباً تغییر نمی‌کنند.'}},
  {type:'quiz',q:{en:'„Kannst du ___ bitte helfen?“',fa:'«Kannst du ___ bitte helfen?»'},
   a:'mir',o:['mich','ich','meiner'],
   ex:{en:'<b>helfen</b> is one of the verbs that take the Dative, so „me“ here is <b>mir</b>, not mich. English „help me“ hides this completely — which is why it has to be learnt as a fixed fact about the verb: <i>jemandem helfen</i>.',
       fa:'<b>helfen</b> از فعل‌هایی است که داتیو می‌گیرند، پس «me» اینجا <b>mir</b> است نه mich. «help me» انگلیسی این را کاملاً پنهان می‌کند؛ پس باید آن را به‌عنوان ویژگی ثابت فعل یاد گرفت: <i>jemandem helfen</i>.'}}
 ]},

/* ============ 5 · present ============ */
{id:'present',ic:'⚡',lv:2,sk:'Verbs',
 title:{en:'Present tense',fa:'زمان حال'},
 sub:{en:'One German tense does the work of three English ones',fa:'یک زمان آلمانی، کار سه زمان انگلیسی را می‌کند'},
 blocks:[
  {type:'text',md:{en:'To conjugate a German verb, cut <b>-en</b> off the infinitive to get the <b>stem</b>, then add the ending for the person. <b class="deword">spielen</b> (to play) → stem <b>spiel-</b> → <i>ich spiele, du spielst…</i> That is the whole machine, and it runs on almost every verb in the language.<br>Better still: this one tense covers three English ones. „Ich spiele Tennis“ is <i>I play</i>, <i>I am playing</i> and — with a future time word — <i>I will play</i>.',
        fa:'برای صرف فعل آلمانی، <b>-en</b> را از مصدر جدا کن تا <b>بُن</b> به دست آید، بعد پایانهٔ شخص را بیفزا. <b class="deword">spielen</b> → بن <b>spiel-</b> → <i>ich spiele, du spielst…</i> همین تمام ماشین است و روی تقریباً همهٔ فعل‌های زبان کار می‌کند. بهتر از آن: همین یک زمان، کار سه زمان انگلیسی را می‌کند.'}},
  {type:'table',head:['','spielen','ending'],rows:[
   ['ich','*spiele','-e'],
   ['du','*spielst','-st'],
   ['er/sie/es','*spielt','-t'],
   ['wir','*spielen','-en'],
   ['ihr','*spielt','-t'],
   ['sie/Sie','*spielen','-en']],
   cap:{en:'Six slots, but only four different endings — wir and sie/Sie are just the infinitive.',
        fa:'شش خانه، اما فقط چهار پایانهٔ متفاوت — wir و sie/Sie همان مصدرند.'}},
  {type:'table',head:['If the stem ends in…','What happens','Example'],rows:[
   ['*-t or -d','insert an *e so you can say it','arbeiten → du *arbeitest, er *arbeitet'],
   ['*-s, -ß, -z, -x','du-ending loses its *s','heißen → du *heißt · reisen → du *reist'],
   ['*-eln','ich-form drops the *e','sammeln → ich *sammle · lächeln → ich *lächle'],
   ['*-ten / -den (ihr too)','ihr gets *-et','ihr *arbeitet, ihr *findet']],
   cap:{en:'These are not exceptions — they are just German refusing to be unpronounceable.',
        fa:'این‌ها استثنا نیستند؛ آلمانی فقط از تلفظ‌ناپذیری پرهیز می‌کند.'}},
  {type:'rule',md:{en:'About 50 common verbs change their <b>stem vowel</b> — but only in <b>du</b> and <b>er/sie/es</b>. Everywhere else they are perfectly regular.<br><b>e → ie</b>: sehen → du s<b>ie</b>hst, er s<b>ie</b>ht · lesen → du l<b>ie</b>st<br><b>e → i</b>: sprechen → du spr<b>i</b>chst · essen → du <b>i</b>sst · nehmen → du n<b>i</b>mmst<br><b>a → ä</b>: fahren → du f<b>ä</b>hrst · schlafen → du schl<b>ä</b>fst · tragen → du tr<b>ä</b>gst<br><b>au → äu</b>: laufen → du l<b>äu</b>fst<br>Learn each one in the <b>du</b> form and the er-form comes free.',
        fa:'حدود ۵۰ فعل پرکاربرد <b>مصوت بُن</b> را عوض می‌کنند — اما فقط در <b>du</b> و <b>er/sie/es</b>. در بقیهٔ اشخاص کاملاً باقاعده‌اند: sehen → du siehst؛ sprechen → du sprichst؛ fahren → du fährst؛ laufen → du läufst. هر فعل را در شکل <b>du</b> یاد بگیر و شکل er مجانی به دست می‌آید.'}},
  {type:'examples',items:[
   {de:'Ich lerne gerade Deutsch.',en:'I am learning German right now.',say:'Ich lerne gerade Deutsch.'},
   {de:'Du sprichst sehr schnell.',en:'You speak very fast. (sprechen → du sprichst)',say:'Du sprichst sehr schnell.'},
   {de:'Er fährt jeden Tag mit dem Fahrrad zur Arbeit.',en:'He cycles to work every day. (fahren → er fährt)',say:'Er fährt jeden Tag mit dem Fahrrad zur Arbeit.'},
   {de:'Wir wohnen seit zwei Jahren in Köln.',en:'We have lived in Cologne for two years.',say:'Wir wohnen seit zwei Jahren in Köln.'},
   {de:'Was arbeitest du?',en:'What do you do for a living? (arbeiten → du arbeitest)',say:'Was arbeitest du?'},
   {de:'Morgen fliege ich nach Istanbul.',en:'Tomorrow I am flying to Istanbul. (present = future)',say:'Morgen fliege ich nach Istanbul.'}]},
  {type:'warn',md:{en:'The error that marks a beginner instantly: building English’s continuous tense in German.<br>„<s>Ich bin lernen</s>“ ✗ · „<s>Ich bin lernend</s>“ ✗ · „<s>Ich bin am lernen</s>“ ✗<br>→ simply „<b>Ich lerne</b>.“ ✓ German has <b>no</b> „am/is/are + -ing“ form at all. If you want to stress that it is happening right now, add a word: <b>gerade</b>, <b>jetzt</b>, <b>im Moment</b>.<br>Second error: forgetting the vowel change, because the pattern is invisible in the infinitive. „<s>du sprechst</s>“ ✗ → <b>du sprichst</b>. „<s>du fahrst</s>“ ✗ → <b>du fährst</b>. „<s>er nehmt</s>“ ✗ → <b>er nimmt</b>.',
        fa:'خطایی که فوراً آغازین‌بودن را لو می‌دهد: ساختن زمان استمراری انگلیسی در آلمانی. «Ich bin lernen» ✗ → فقط «<b>Ich lerne</b>» ✓. آلمانی هیچ شکل «am/is/are + -ing» ندارد؛ اگر می‌خواهی تأکید کنی که همین حالا رخ می‌دهد، واژه‌ای بیفزا: <b>gerade</b>، <b>jetzt</b>، <b>im Moment</b>. خطای دوم: فراموش‌کردن تغییر مصوت — «du sprechst» ✗ → <b>du sprichst</b>.'}},
  {type:'tip',md:{en:'You can postpone the future tense for a long time. With a time word, the present <i>is</i> the future, and that is what Germans actually say: „<b>Morgen</b> fahre ich nach Hamburg“, „<b>Nächste Woche</b> fängt der Kurs an“, „Ich rufe dich <b>später</b> an“. „Ich werde fahren“ is correct but sounds heavier and is used less than English „will“.',
        fa:'می‌توانی زمان آینده را مدت‌ها به تعویق بیندازی. با یک قید زمان، حالِ آلمانی همان آینده است و آلمانی‌زبان‌ها هم همین را می‌گویند: «Morgen fahre ich nach Hamburg». «Ich werde fahren» درست است اما سنگین‌تر و کم‌کاربردتر از «will» انگلیسی.'}},
  {type:'quiz',q:{en:'„Du ___ viel zu schnell.“ (sprechen)',fa:'«Du ___ viel zu schnell.» (sprechen)'},
   a:'sprichst',o:['sprechst','sprecht','sprechen'],
   ex:{en:'<b>sprechen</b> is an <i>e → i</i> verb, and the change happens in exactly two forms: <b>du sprichst</b> and <b>er/sie/es spricht</b>. Everywhere else the stem stays <i>sprech-</i>: wir sprechen, ihr sprecht.',
       fa:'<b>sprechen</b> فعل <i>e → i</i> است و تغییر دقیقاً در دو شکل رخ می‌دهد: <b>du sprichst</b> و <b>er spricht</b>. در بقیه بن همان <i>sprech-</i> می‌ماند.'}}
 ]},

/* ============ 6 · seinhaben ============ */
{id:'seinhaben',ic:'🔑',lv:2,sk:'Verbs',
 title:{en:'sein & haben',fa:'sein و haben'},
 sub:{en:'The two verbs you cannot get around',fa:'دو فعلی که نمی‌توان از آن‌ها گریخت'},
 blocks:[
  {type:'text',md:{en:'<b class="deword">sein</b> (to be) and <b class="deword">haben</b> (to have) are the two most frequent verbs in German, and both are completely irregular. There is no stem to work from — you simply know them. It is worth the effort twice over, because later they become the <b>helper verbs</b> that build the past tense: „ich <b>habe</b> gegessen“, „ich <b>bin</b> gefahren“. Every past sentence you ever say will start with one of these six forms.',
        fa:'<b class="deword">sein</b> (بودن) و <b class="deword">haben</b> (داشتن) دو فعل پرکاربردترین آلمانی‌اند و هر دو کاملاً بی‌قاعده. بُنی نیست که از آن بسازی — فقط حفظشان می‌کنی. ارزش این زحمت دوبرابر است، چون بعدها همین دو فعل، <b>فعل کمکی</b> ساختن زمان گذشته می‌شوند: «ich habe gegessen»، «ich bin gefahren».'}},
  {type:'table',head:['','sein (to be)','haben (to have)'],rows:[
   ['ich','*bin','*habe'],
   ['du','*bist','*hast'],
   ['er/sie/es','*ist','*hat'],
   ['wir','*sind','*haben'],
   ['ihr','*seid','*habt'],
   ['sie/Sie','*sind','*haben']],
   cap:{en:'Note seid (ihr) — no h — against sind (wir/sie). Those two are the ones that get swapped.',
        fa:'به seid (برای ihr) دقت کن — بدون h — در برابر sind. همین دو با هم جابه‌جا می‌شوند.'}},
  {type:'rule',md:{en:'The division of labour is clean:<br><b>sein</b> + a noun or adjective — who or what something <i>is</i>: „Ich <b>bin</b> Lehrer.“ „Das <b>ist</b> teuer.“ „Wir <b>sind</b> müde.“<br><b>haben</b> + an Accusative object — what someone <i>has</i>: „Ich <b>habe</b> ein Auto.“ „Hast du Zeit?“<br>After <b>sein</b> there is no object, so nothing changes case: „Das ist <b>ein</b> guter Film“, never „einen“.',
        fa:'تقسیم کار روشن است: <b>sein</b> + اسم یا صفت — اینکه چیزی چه <i>هست</i>: «Ich bin Lehrer.» <b>haben</b> + مفعول مستقیم — اینکه کسی چه <i>دارد</i>: «Ich habe ein Auto.» پس از <b>sein</b> مفعولی نیست، پس حالت تغییر نمی‌کند: «Das ist <b>ein</b> guter Film»، هرگز «einen».'}},
  {type:'contrast',cols:[
   {t:'English „be“ → German haben',md:{en:'German treats these as things you <i>possess</i>, not states you are in:<br>„Ich <b>habe</b> Hunger.“ — I am hungry.<br>„Ich <b>habe</b> Durst.“ — I am thirsty.<br>„Ich <b>habe</b> Angst.“ — I am afraid.<br>„Du <b>hast</b> recht.“ — You are right.<br>„Ich <b>habe</b> kalt“ ✗ is the exception — for temperature say „<b>Mir ist</b> kalt.“'}},
   {t:'English „have“ → German sein',md:{en:'And age goes the other way round:<br>„Ich <b>bin</b> 30 Jahre alt.“ — I am 30.<br>„Wie alt <b>bist</b> du?“ — How old are you?<br>Also with jobs, and without an article:<br>„Sie <b>ist</b> Ärztin.“ — She is a doctor.<br>„Ich <b>bin</b> Student.“ — I am a student.'}}]},
  {type:'examples',items:[
   {de:'Ich bin heute sehr müde.',en:'I am very tired today.',say:'Ich bin heute sehr müde.'},
   {de:'Meine Schwester ist Ärztin.',en:'My sister is a doctor. (no article with professions)',say:'Meine Schwester ist Ärztin.'},
   {de:'Hast du heute Abend Zeit?',en:'Do you have time this evening?',say:'Hast du heute Abend Zeit?'},
   {de:'Wir haben leider kein Bargeld.',en:'Unfortunately we have no cash.',say:'Wir haben leider kein Bargeld.'},
   {de:'Ihr seid schon da — wunderbar!',en:'You are here already — wonderful!',say:'Ihr seid schon da — wunderbar!'},
   {de:'Ich habe großen Hunger.',en:'I am very hungry. (literally: I have great hunger)',say:'Ich habe großen Hunger.'}]},
  {type:'warn',md:{en:'Three traps, all caused by translating word for word:<br>1. „<s>Ich bin Hunger</s>“ ✗ → „Ich <b>habe</b> Hunger.“ ✓ Hunger, Durst, Angst, Glück and recht are all <i>had</i>, not <i>been</i>.<br>2. „<s>Ich habe 30 Jahre</s>“ ✗ → „Ich <b>bin</b> 30 Jahre alt.“ ✓ (That mistake comes from French and Spanish; German agrees with English here.)<br>3. „<s>Sie ist eine Ärztin</s>“ ✗ → „Sie ist <b>Ärztin</b>.“ ✓ With professions, nationalities and religions German drops the article entirely: „Er ist Deutscher“, „Ich bin Ingenieur“.',
        fa:'سه دام، همه از ترجمهٔ واژه‌به‌واژه: ۱) «Ich bin Hunger» ✗ → «Ich <b>habe</b> Hunger» ✓. ۲) «Ich habe 30 Jahre» ✗ → «Ich <b>bin</b> 30 Jahre alt» ✓. ۳) «Sie ist eine Ärztin» ✗ → «Sie ist <b>Ärztin</b>» ✓ — با شغل، ملیت و دین، آلمانی حرف تعریف را حذف می‌کند.'}},
  {type:'tip',md:{en:'Both verbs also carry the polite forms you will want immediately: <b>wäre</b> („wäre das möglich?“ — would that be possible?) and <b>hätte</b> („ich <b>hätte</b> gern einen Kaffee“ — I would like a coffee). „Ich hätte gern…“ is the single most useful phrase for ordering anything in Germany.',
        fa:'هر دو فعل شکل مؤدبانه‌ای دارند که فوراً به کارت می‌آید: <b>wäre</b> («wäre das möglich؟») و <b>hätte</b> («ich hätte gern einen Kaffee»). «Ich hätte gern…» پرکاربردترین عبارت برای سفارش‌دادن در آلمان است.'}},
  {type:'quiz',q:{en:'„Ich ___ Durst. Gibt es Wasser?“',fa:'«Ich ___ Durst. Gibt es Wasser?»'},
   a:'habe',o:['bin','ist','hat'],
   ex:{en:'German <i>has</i> thirst rather than <i>being</i> thirsty: „Ich <b>habe</b> Durst.“ Same for Hunger and Angst. The only common exception is temperature, where you say „Mir ist kalt / warm“.',
       fa:'آلمانی تشنگی را <i>دارد</i>، نه اینکه تشنه <i>باشد</i>: «Ich <b>habe</b> Durst.» برای Hunger و Angst هم همین‌طور. تنها استثنای رایج دماست: «Mir ist kalt».'}}
 ]},

/* ============ 7 · wordorder ============ */
{id:'wordorder',ic:'🧩',lv:2,sk:'Sentences',
 title:{en:'Word order: the verb in position 2',fa:'ترتیب واژه: فعل در جایگاه دوم'},
 sub:{en:'Why „Heute ich gehe“ is the most common beginner error',fa:'چرا «Heute ich gehe» رایج‌ترین خطای آغازین است'},
 blocks:[
  {type:'text',md:{en:'A German statement is built around <b>one fixed point</b>: the conjugated verb stands in <b>position 2</b>. Not second word — second <i>element</i>. Everything else can move around it for emphasis, which is why German word order feels so free; but the verb never moves. Think of it as a hinge: the sentence swings around it, the hinge stays put.<br>Why can German do this? Because the <i>articles</i> show who does what (der/den, dem), the position no longer has to. English, which dropped most of its endings, has to keep subject-verb-object order instead.',
        fa:'جملهٔ خبری آلمانی حول <b>یک نقطهٔ ثابت</b> ساخته می‌شود: فعل صرف‌شده در <b>جایگاه دوم</b> است. نه واژهٔ دوم — <i>عنصر</i> دوم. هر چیز دیگری می‌تواند برای تأکید جابه‌جا شود، و همین است که ترتیب واژه در آلمانی آزاد به نظر می‌رسد؛ اما فعل هرگز جابه‌جا نمی‌شود. چرا آلمانی می‌تواند چنین کند؟ چون <i>حرف تعریف</i> نشان می‌دهد کی چه کرده، پس جایگاه لازم نیست این کار را بکند.'}},
  {type:'rule',md:{en:'„Position 1“ holds <b>one element</b>, however many words that element contains. All of these are a single element:<br>„<b>Ich</b>“ · „<b>Mein kleiner Bruder</b>“ · „<b>Heute Abend</b>“ · „<b>Nach der Arbeit</b>“ · „<b>Weil ich müde bin</b>“<br>Whatever you put there, the verb follows immediately — and if position 1 is not the subject, the subject hops to position 3, right behind the verb.',
        fa:'«جایگاه ۱» <b>یک عنصر</b> را در خود دارد، هر چند واژه که داشته باشد. همهٔ این‌ها یک عنصرند: «Ich»، «Mein kleiner Bruder»، «Heute Abend»، «Nach der Arbeit»، «Weil ich müde bin». هر چه آنجا بگذاری، فعل بی‌درنگ پس از آن می‌آید — و اگر جایگاه ۱ فاعل نباشد، فاعل به جایگاه ۳ می‌پرد، درست پشت فعل.'}},
  {type:'table',head:['1 — anything','2 — verb','3+ — the rest'],rows:[
   ['Ich','*lerne','heute Deutsch.'],
   ['Heute','*lerne','ich Deutsch.'],
   ['Deutsch','*lerne','ich seit zwei Jahren.'],
   ['In Berlin','*wohnt','meine Schwester.'],
   ['Mein kleiner Bruder','*spielt','sehr gut Klavier.'],
   ['Nach der Arbeit','*gehe','ich schwimmen.'],
   ['Leider','*habe','ich keine Zeit.']],
   cap:{en:'Six different openings, one unmoved verb. Notice the subject „ich“ sliding behind it.',
        fa:'شش آغاز متفاوت، یک فعل بی‌حرکت. دقت کن که فاعل «ich» پشت آن می‌سُرد.'}},
  {type:'contrast',cols:[
   {t:'Statement — verb 2nd',md:{en:'„Morgen <b>fahren</b> wir nach Hamburg.“<br>„Meine Eltern <b>kommen</b> am Freitag.“<br>Something fills slot 1, the verb takes slot 2.'}},
   {t:'Question — verb 1st or after W',md:{en:'Yes/no → verb first:<br>„<b>Fahren</b> wir morgen nach Hamburg?“<br>„<b>Hast</b> du Zeit?“<br>W-question → question word fills slot 1, so the verb is still 2nd:<br>„<b>Wann</b> <b>fahren</b> wir?“ · „<b>Wo</b> <b>wohnst</b> du?“'}}]},
  {type:'examples',items:[
   {de:'Am Wochenende besuche ich meine Eltern.',en:'At the weekend I visit my parents.',say:'Am Wochenende besuche ich meine Eltern.'},
   {de:'Wo wohnst du genau?',en:'Where exactly do you live?',say:'Wo wohnst du genau?'},
   {de:'Trinkst du Kaffee oder Tee?',en:'Do you drink coffee or tea?',say:'Trinkst du Kaffee oder Tee?'},
   {de:'Warum lernst du Deutsch?',en:'Why are you learning German?',say:'Warum lernst du Deutsch?'},
   {de:'Leider habe ich heute keine Zeit.',en:'Unfortunately I have no time today.',say:'Leider habe ich heute keine Zeit.'},
   {de:'Jeden Morgen fahre ich mit dem Bus zur Arbeit.',en:'Every morning I take the bus to work.',say:'Jeden Morgen fahre ich mit dem Bus zur Arbeit.'}]},
  {type:'warn',md:{en:'This is <b>the</b> beginner error, and it survives for years because English never punishes it. English says „Today I go to the cinema“ — subject stays first. German cannot:<br>„<s>Heute ich gehe ins Kino.</s>“ ✗<br>→ „<b>Heute gehe ich</b> ins Kino.“ ✓<br>„<s>Morgen wir fahren nach Köln.</s>“ ✗ → „<b>Morgen fahren wir</b> nach Köln.“ ✓<br>„<s>Leider ich habe keine Zeit.</s>“ ✗ → „<b>Leider habe ich</b> keine Zeit.“ ✓<br>The habit to build: <b>whenever a sentence does not start with the subject, swap the next two things.</b> Say it out loud as verb-then-subject until it feels normal.',
        fa:'این <b>همان</b> خطای آغازین است و سال‌ها می‌ماند، چون انگلیسی هرگز تنبیهش نمی‌کند. انگلیسی می‌گوید «Today I go…» و فاعل اول می‌ماند. آلمانی نمی‌تواند: «Heute ich gehe ins Kino» ✗ → «<b>Heute gehe ich</b> ins Kino» ✓. عادتی که باید بسازی: <b>هر وقت جمله با فاعل آغاز نشد، دو چیز بعدی را جابه‌جا کن.</b>'}},
  {type:'tip',md:{en:'For the middle of the sentence, there is a reliable default order: <b>TeKaMoLo</b> — <b>Te</b>mporal (when), <b>Ka</b>usal (why), <b>Mo</b>dal (how), <b>Lo</b>kal (where).<br>„Ich fahre <b>morgen</b> <b>wegen der Prüfung</b> <b>mit dem Zug</b> <b>nach Hamburg</b>.“<br>Also: pronouns like to come early, and short before long — „Ich gebe <b>es dir</b> morgen.“',
        fa:'برای میانهٔ جمله ترتیب پیش‌فرض قابل‌اعتمادی هست: <b>TeKaMoLo</b> — زمان، دلیل، شیوه، مکان. «Ich fahre <b>morgen</b> <b>wegen der Prüfung</b> <b>mit dem Zug</b> <b>nach Hamburg</b>.» و ضمایر دوست دارند زود بیایند؛ کوتاه پیش از بلند.'}},
  {type:'quiz',q:{en:'Which sentence is correct German?',fa:'کدام جمله آلمانیِ درست است؟'},
   a:'Morgen gehe ich ins Kino.',o:['Morgen ich gehe ins Kino.','Ich morgen gehe ins Kino.','Morgen ins Kino gehe ich.'],
   ex:{en:'„Morgen“ takes position 1, so the verb <b>gehe</b> must take position 2 and the subject <i>ich</i> moves behind it. The first wrong option keeps English order; the third tries to squeeze <i>two</i> elements into position 1.',
       fa:'«Morgen» جایگاه ۱ را می‌گیرد، پس فعل <b>gehe</b> باید جایگاه ۲ را بگیرد و فاعل <i>ich</i> پشت آن برود. گزینهٔ نخست ترتیب انگلیسی را نگه داشته؛ گزینهٔ سوم می‌خواهد <i>دو</i> عنصر را در جایگاه ۱ جا کند.'}}
 ]},

/* ============ 8 · nomakk ============ */
{id:'nomakk',ic:'🎯',lv:3,sk:'Cases',
 title:{en:'Nominative & Accusative',fa:'نهادی و مفعولی (نومیناتیو و آکوزاتیو)'},
 sub:{en:'Who does it, who gets it — and why German has cases at all',fa:'کی انجام می‌دهد، کی دریافت می‌کند — و اصلاً چرا آلمانی حالت دارد'},
 blocks:[
  {type:'text',md:{en:'In English, „the dog bites the man“ and „the man bites the dog“ use the same words and mean opposite things. Only the <b>order</b> tells you who bit whom — so English order is locked.<br>German solved the problem differently: it puts a label on the word itself. <b>Nominativ</b> labels the doer, <b>Akkusativ</b> labels the thing the action lands on. Once the label is there, the order is free, and German uses that freedom to put the most interesting thing first. Cases are not decoration; they are what pays for German word order.',
        fa:'در انگلیسی «the dog bites the man» و «the man bites the dog» واژه‌های یکسانی دارند و معنای مخالف. فقط <b>ترتیب</b> می‌گوید کی کی را گزیده — پس ترتیب انگلیسی قفل است. آلمانی مسئله را جور دیگری حل کرد: برچسب را روی خود واژه می‌گذارد. <b>نومیناتیو</b> کنندهٔ کار را نشان می‌دهد و <b>آکوزاتیو</b> چیزی را که عمل بر آن فرود می‌آید. وقتی برچسب هست، ترتیب آزاد می‌شود. حالت‌ها تزئین نیستند؛ بهایی هستند که آزادی ترتیب واژه را می‌خرند.'}},
  {type:'table',head:['','mask.','fem.','neut.','Plural'],rows:[
   ['Nominativ','der','die','das','die'],
   ['Akkusativ','*den','die','das','die'],
   ['Nom. — ein','ein','eine','ein','—'],
   ['Akk. — ein','*einen','eine','ein','—'],
   ['Nom. — kein/mein','kein','keine','kein','keine'],
   ['Akk. — kein/mein','*keinen','keine','kein','keine']],
   cap:{en:'Look at the stars: in the whole Accusative only the masculine changes. Three of the four columns do nothing.',
        fa:'به ستاره‌ها نگاه کن: در کل آکوزاتیو فقط مذکر تغییر می‌کند. سه ستون از چهار ستون هیچ کاری نمی‌کنند.'}},
  {type:'steps',items:[
   {en:'Find the <b>conjugated verb</b>. Everything hangs off it.',fa:'<b>فعل صرف‌شده</b> را پیدا کن. همه‌چیز به آن آویزان است.'},
   {en:'Ask <b>wer?</b> („who is doing this?“). That word is <b>Nominativ</b> — it gets der/die/das, ein/eine/ein.',fa:'بپرس <b>wer?</b> («کی این کار را می‌کند؟»). آن واژه <b>نومیناتیو</b> است.'},
   {en:'Ask <b>wen oder was?</b> („doing it to whom or what?“). That word is <b>Akkusativ</b> — masculine becomes den/einen/keinen.',fa:'بپرس <b>wen oder was?</b> («روی کی یا چه؟»). آن واژه <b>آکوزاتیو</b> است — مذکر می‌شود den/einen/keinen.'},
   {en:'If the verb is <b>sein, werden</b> or <b>bleiben</b>, stop: those verbs have no object, so both sides stay Nominativ. „Er ist <b>ein</b> guter Lehrer.“',fa:'اگر فعل <b>sein، werden</b> یا <b>bleiben</b> بود، بایست: این فعل‌ها مفعول ندارند و هر دو طرف نومیناتیو می‌مانند. «Er ist <b>ein</b> guter Lehrer.»'},
   {en:'Only one noun in the sentence? Then it is almost certainly the subject → Nominativ.',fa:'اگر جمله فقط یک اسم داشت، تقریباً مطمئناً فاعل است → نومیناتیو.'}]},
  {type:'contrast',cols:[
   {t:'English: order decides',md:{en:'„The man sees the dog.“<br>„The dog sees the man.“<br>Move a word and you change the meaning. You may not reorder for emphasis.'}},
   {t:'German: the article decides',md:{en:'„<b>Der</b> Mann sieht <b>den</b> Hund.“<br>„<b>Den</b> Hund sieht <b>der</b> Mann.“<br>Both mean <i>the man sees the dog</i>. The second simply puts the dog in the spotlight. <b>den</b> is the object wherever it stands.'}}]},
  {type:'examples',items:[
   {de:'Der Mann sieht den Hund.',en:'The man sees the dog.',say:'Der Mann sieht den Hund.'},
   {de:'Ich kaufe einen Kaffee und ein Brötchen.',en:'I am buying a coffee and a roll.',say:'Ich kaufe einen Kaffee und ein Brötchen.'},
   {de:'Ich suche meinen Schlüssel.',en:'I am looking for my key.',say:'Ich suche meinen Schlüssel.'},
   {de:'Wir brauchen keinen Regenschirm.',en:'We do not need an umbrella.',say:'Wir brauchen keinen Regenschirm.'},
   {de:'Sie liest das Buch sehr langsam.',en:'She reads the book very slowly. (das does not change in the Akkusativ)',say:'Sie liest das Buch sehr langsam.'},
   {de:'Mein Bruder ist Lehrer.',en:'My brother is a teacher. (sein → Nominativ, no article)',say:'Mein Bruder ist Lehrer.'}]},
  {type:'warn',md:{en:'The classic English-speaker error: reaching for the <b>subject form</b> because English word order already told you it is the object.<br>„<s>Ich sehe der Mann.</s>“ ✗ → „Ich sehe <b>den</b> Mann.“ ✓<br>„<s>Ich habe ein Bruder.</s>“ ✗ → „Ich habe <b>einen</b> Bruder.“ ✓<br>„<s>Ich trinke der Kaffee.</s>“ ✗ → „Ich trinke <b>den</b> Kaffee.“ ✓<br>And the mirror-image overcorrection, once you have learnt <i>den</i>: „<s>Er ist einen Lehrer.</s>“ ✗ → „Er ist Lehrer.“ ✓ <b>sein</b> never takes an Accusative. Nor do the prepositions aus, bei, mit, nach, seit, von, zu — those need the Dative.',
        fa:'خطای کلاسیک انگلیسی‌زبان‌ها: استفاده از <b>شکل فاعلی</b> چون ترتیب انگلیسی از قبل گفته که این مفعول است. «Ich sehe der Mann» ✗ → «Ich sehe <b>den</b> Mann» ✓. «Ich habe ein Bruder» ✗ → «<b>einen</b> Bruder» ✓. و افراط معکوس بعد از یادگرفتن den: «Er ist einen Lehrer» ✗ → «Er ist Lehrer» ✓؛ <b>sein</b> هرگز آکوزاتیو نمی‌گیرد.'}},
  {type:'tip',md:{en:'Here is the practical shortcut. In the Accusative, feminine, neuter and plural look <i>exactly</i> like the Nominative. So you do not have to think about the whole system — you only have to watch <b>der-words</b>. Scan your sentence for masculine objects and change der→den, ein→einen, mein→meinen, kein→keinen. Everything else you already know.',
        fa:'میان‌بُر عملی: در آکوزاتیو، مؤنث، خنثی و جمع <i>دقیقاً</i> مثل نومیناتیو هستند. پس لازم نیست به کل نظام فکر کنی — فقط باید <b>واژه‌های مذکر</b> را بپایی: der→den، ein→einen، mein→meinen، kein→keinen.'}},
  {type:'quiz',q:{en:'„Ich habe ___ Bruder und eine Schwester.“',fa:'«Ich habe ___ Bruder und eine Schwester.»'},
   a:'einen',o:['ein','einem','eines'],
   ex:{en:'<b>haben</b> takes an Accusative object, and <i>Bruder</i> is masculine — so <b>ein → einen</b>. Compare the feminine <i>Schwester</i> in the same sentence: it stays <b>eine</b>, because only the masculine changes.',
       fa:'<b>haben</b> مفعول آکوزاتیو می‌گیرد و <i>Bruder</i> مذکر است، پس <b>ein → einen</b>. <i>Schwester</i> مؤنث در همان جمله <b>eine</b> می‌ماند، چون فقط مذکر تغییر می‌کند.'}}
 ]},

/* ============ 9 · dativ ============ */
{id:'dativ',ic:'🎁',lv:3,sk:'Cases',
 title:{en:'The Dative case',fa:'حالت داتیو'},
 sub:{en:'The receiver — and how to spot one without translating',fa:'دریافت‌کننده — و شناختنش بدون ترجمه'},
 blocks:[
  {type:'text',md:{en:'If the Nominative is the <i>doer</i> and the Accusative is the <i>thing acted on</i>, the Dative is the <b>person the action is aimed at</b> — the one who receives it, benefits from it, or is affected by it. In „I give the child a ball“, the ball is handed over (Accusative) and the child is who it goes to (Dative).<br>The reason it feels hard is not the grammar; it is that English marks the same idea with a little word („to the child“, „for my sister“) or with nothing at all. German marks it on the article instead, and sometimes marks it where English gives no hint whatsoever.',
        fa:'اگر نومیناتیو <i>کنندهٔ کار</i> و آکوزاتیو <i>چیزی که عمل بر آن می‌افتد</i> باشد، داتیو <b>کسی است که عمل به سوی او نشانه رفته</b> — دریافت‌کننده، بهره‌مند، یا کسی که تحت تأثیر است. در «ball را به کودک می‌دهم»، توپ دست‌به‌دست می‌شود (آکوزاتیو) و کودک مقصد است (داتیو). دشواری‌اش دستور نیست؛ این است که انگلیسی همان مفهوم را با واژهٔ کوچکی («to», «for») یا با هیچ نشان می‌دهد، و آلمانی آن را روی حرف تعریف نشان می‌دهد.'}},
  {type:'table',head:['','mask.','fem.','neut.','Plural'],rows:[
   ['Nominativ','der','die','das','die'],
   ['Akkusativ','den','die','das','die'],
   ['Dativ','*dem','*der','*dem','*den + -n'],
   ['Dativ — ein','*einem','*einer','*einem','—'],
   ['Dativ — mein','*meinem','*meiner','*meinem','*meinen + -n']],
   cap:{en:'In the Dative everything changes — and the plural noun itself takes an extra -n: mit den Kindern, mit den Freunden.',
        fa:'در داتیو همه‌چیز تغییر می‌کند — و خودِ اسم جمع یک ‎-n‎ اضافه می‌گیرد: mit den Kindern، mit den Freunden.'}},
  {type:'steps',items:[
   {en:'Is the noun right after <b>aus, bei, mit, nach, seit, von, zu</b> (or gegenüber)? → <b>Dativ</b>, no further thought needed.',fa:'آیا اسم بی‌درنگ پس از <b>aus، bei، mit، nach، seit، von، zu</b> آمده؟ → <b>داتیو</b>، بی هیچ فکر دیگری.'},
   {en:'Is the verb one of the <b>Dative verbs</b> — helfen, danken, gehören, gefallen, antworten, passen, schmecken, gratulieren? → its single object is <b>Dativ</b>.',fa:'آیا فعل از <b>فعل‌های داتیوی</b> است — helfen، danken، gehören، gefallen، antworten، passen، schmecken، gratulieren؟ → تنها مفعولش <b>داتیو</b> است.'},
   {en:'Are there <b>two</b> objects, a person and a thing? → person = <b>Dativ</b>, thing = <b>Akkusativ</b>. „Ich schenke <b>meiner Mutter</b> <b>einen Schal</b>.“',fa:'آیا <b>دو</b> مفعول هست، یک شخص و یک چیز؟ → شخص = <b>داتیو</b>، چیز = <b>آکوزاتیو</b>.'},
   {en:'Still unsure? Ask <b>wem?</b> If the English can take „to…“ or „for…“ in front of it, it is Dative.',fa:'باز هم مطمئن نیستی؟ بپرس <b>wem?</b> اگر در انگلیسی بتوان پیش از آن «to» یا «for» گذاشت، داتیو است.'},
   {en:'Two-way preposition (in, an, auf, über, unter, vor, hinter, neben, zwischen)? Then ask <b>wo?</b> → Dativ, or <b>wohin?</b> → Akkusativ.',fa:'حرف اضافهٔ دوحالته (in، an، auf، über، unter، vor، hinter، neben، zwischen)؟ بپرس <b>wo?</b> → داتیو، یا <b>wohin?</b> → آکوزاتیو.'}]},
  {type:'contrast',cols:[
   {t:'Akkusativ — wen?',md:{en:'The verb acts <i>on</i> it.<br>„Ich <b>frage den</b> Lehrer.“ — I ask the teacher.<br>„Ich <b>sehe das</b> Kind.“<br>„Ich <b>rufe meinen</b> Bruder an.“'}},
   {t:'Dativ — wem?',md:{en:'The verb is aimed <i>at</i> it.<br>„Ich <b>antworte dem</b> Lehrer.“ — I answer the teacher.<br>„Ich <b>helfe dem</b> Kind.“<br>„Ich <b>glaube meinem</b> Bruder.“<br>Same English shape, different German case — which is why these verbs have to be memorised individually.'}}]},
  {type:'examples',items:[
   {de:'Ich gebe dem Kind einen Ball.',en:'I give the child a ball. (person Dativ, thing Akkusativ)',say:'Ich gebe dem Kind einen Ball.'},
   {de:'Ich helfe meiner Schwester bei den Hausaufgaben.',en:'I help my sister with her homework.',say:'Ich helfe meiner Schwester bei den Hausaufgaben.'},
   {de:'Das Fahrrad gehört meinem Nachbarn.',en:'The bike belongs to my neighbour.',say:'Das Fahrrad gehört meinem Nachbarn.'},
   {de:'Wie geht es deiner Mutter?',en:'How is your mother?',say:'Wie geht es deiner Mutter?'},
   {de:'Das Essen schmeckt mir sehr gut.',en:'The food tastes very good to me.',say:'Das Essen schmeckt mir sehr gut.'},
   {de:'Ich fahre mit den Kindern zum Zahnarzt.',en:'I am driving to the dentist with the children. (plural -n)',say:'Ich fahre mit den Kindern zum Zahnarzt.'}]},
  {type:'warn',md:{en:'The trap is that English gives you <b>no signal</b>. „I help the woman“ looks like a plain object, so you write an object — and it is wrong:<br>„<s>Ich helfe die Frau.</s>“ ✗ → „Ich helfe <b>der</b> Frau.“ ✓<br>„<s>Kannst du mich helfen?</s>“ ✗ → „Kannst du <b>mir</b> helfen?“ ✓<br>„<s>Ich danke dich.</s>“ ✗ → „Ich danke <b>dir</b>.“ ✓<br>And the detail everyone forgets: the <b>plural noun takes an extra -n</b> in the Dative. „<s>mit den Kinder</s>“ ✗ → „mit den <b>Kindern</b>“ ✓; „mit den <b>Freunden</b>“, „in den <b>Städten</b>“. Nouns whose plural already ends in -n or -s are left alone: „mit den Frauen“, „mit den Autos“.',
        fa:'دام این است که انگلیسی <b>هیچ نشانی</b> نمی‌دهد. «I help the woman» مفعول ساده به نظر می‌رسد، پس مفعول می‌نویسی — و غلط است: «Ich helfe die Frau» ✗ → «Ich helfe <b>der</b> Frau» ✓. «Ich danke dich» ✗ → «Ich danke <b>dir</b>» ✓. و جزئیاتی که همه فراموش می‌کنند: <b>اسم جمع در داتیو یک ‎-n‎ اضافه می‌گیرد</b>: «mit den <b>Kindern</b>».'}},
  {type:'tip',md:{en:'A fast reading trick: in a sentence with two nouns and no preposition, the <b>person</b> is the Dative and the <b>thing</b> is the Accusative — and the Dative comes <i>first</i>. „Ich kaufe <b>meinem Vater</b> <b>ein Buch</b>.“ Order flips only when the thing is a pronoun: „Ich kaufe <b>es</b> meinem Vater.“',
        fa:'ترفند سریع خواندن: در جمله‌ای با دو اسم و بدون حرف اضافه، <b>شخص</b> داتیو است و <b>چیز</b> آکوزاتیو — و داتیو <i>اول</i> می‌آید. «Ich kaufe <b>meinem Vater</b> <b>ein Buch</b>.» ترتیب فقط وقتی برمی‌گردد که «چیز» ضمیر باشد: «Ich kaufe <b>es</b> meinem Vater.»'}},
  {type:'quiz',q:{en:'„Das Auto gehört ___ Lehrerin.“',fa:'«Das Auto gehört ___ Lehrerin.»'},
   a:'der',o:['die','den','dem'],
   ex:{en:'<b>gehören</b> always takes the Dative, and <i>Lehrerin</i> is feminine. Feminine Dative is <b>der</b> — the same shape as masculine Nominative, which is exactly why this one feels wrong at first. „Das Auto gehört <b>der</b> Lehrerin.“',
       fa:'<b>gehören</b> همیشه داتیو می‌گیرد و <i>Lehrerin</i> مؤنث است. داتیوِ مؤنث <b>der</b> است — همان شکلِ نومیناتیوِ مذکر، و همین است که اول عجیب به نظر می‌رسد.'}}
 ]},

/* ============ 10 · plural ============ */
{id:'plural',ic:'🧺',lv:3,sk:'Plurals',
 title:{en:'Plural nouns',fa:'جمع اسم‌ها'},
 sub:{en:'Five patterns — and why -s is almost always wrong',fa:'پنج الگو — و چرا ‎-s‎ تقریباً همیشه غلط است'},
 blocks:[
  {type:'text',md:{en:'German has <b>no single plural rule</b>. What it has is five patterns, and a strong correlation with gender — so you can guess far better than randomly. Two pieces of good news: the plural article is <b>always die</b>, in every gender, and the plural is a fixed property of the word, like its gender. Learn nouns in threes from the start — <b>der Tisch, die Tische</b> — and the problem never arises.',
        fa:'آلمانی <b>یک قاعدهٔ جمع ندارد</b>. پنج الگو دارد و هم‌بستگی قوی با جنس دستوری — پس می‌توانی خیلی بهتر از شانس حدس بزنی. دو خبر خوب: حرف تعریف جمع <b>همیشه die</b> است، در هر جنسی؛ و جمع ویژگی ثابت واژه است، مثل جنسش. از همان اول اسم‌ها را سه‌تایی یاد بگیر — <b>der Tisch, die Tische</b> — و این مشکل هرگز پیش نمی‌آید.'}},
  {type:'table',head:['Pattern','Typically','Singular','Plural'],rows:[
   ['*-e','many masculine','der Tisch','die Tisch*e'],
   ['*-e + Umlaut','masculine','der Stuhl','die St*ühle'],
   ['*-er','some neuter','das Kind','die Kind*er'],
   ['*-er + Umlaut','neuter & masculine','das Buch','die B*ücher'],
   ['*-(e)n','almost all feminine','die Frau','die Frau*en'],
   ['*-nen','feminine in -in','die Lehrerin','die Lehrerin*nen'],
   ['*-s','loanwords','das Auto','die Auto*s'],
   ['*no change','masc. in -er, -el, -en','der Lehrer','die Lehrer'],
   ['*Umlaut only','masc. in -er, -el','der Vater','die V*äter']],
   cap:{en:'Column 2 is the useful one: the gender narrows the guess down to one or two options.',
        fa:'ستون دوم مفید است: جنس دستوری حدس را به یکی دو گزینه محدود می‌کند.'}},
  {type:'rule',md:{en:'Three shortcuts that are almost always right:<br>1. <b>Feminine → -(e)n.</b> die Frau → Frauen, die Zeitung → Zeitungen, die Schwester → Schwestern. Around 95% of feminine nouns, and they <i>never</i> take an Umlaut.<br>2. <b>-in → -innen.</b> Double the n: Lehrerin → Lehrerinnen, Studentin → Studentinnen.<br>3. <b>-chen and -lein never change.</b> das Mädchen → die Mädchen, das Brötchen → die Brötchen. (They are also always neuter.)',
        fa:'سه میان‌بُر که تقریباً همیشه درست‌اند: ۱) <b>مؤنث → ‎-(e)n</b> — نزدیک ۹۵٪ اسم‌های مؤنث، و <i>هرگز</i> اوملاوت نمی‌گیرند. ۲) <b>‎-in → -innen</b>، با دو n. ۳) <b>‎-chen و -lein هرگز تغییر نمی‌کنند</b> و همیشه خنثی‌اند.'}},
  {type:'examples',items:[
   {de:'Ich habe zwei Brüder und eine Schwester.',en:'I have two brothers and one sister.',say:'Ich habe zwei Brüder und eine Schwester.'},
   {de:'Die Äpfel sind diese Woche sehr teuer.',en:'The apples are very expensive this week.',say:'Die Äpfel sind diese Woche sehr teuer.'},
   {de:'Die Bücher liegen auf dem Tisch.',en:'The books are lying on the table.',say:'Die Bücher liegen auf dem Tisch.'},
   {de:'In unserer Schule arbeiten viele Lehrerinnen.',en:'Many female teachers work at our school.',say:'In unserer Schule arbeiten viele Lehrerinnen.'},
   {de:'Wir brauchen noch zwei Stühle.',en:'We still need two chairs.',say:'Wir brauchen noch zwei Stühle.'},
   {de:'Meine Eltern wohnen in Hamburg.',en:'My parents live in Hamburg. (plural-only noun)',say:'Meine Eltern wohnen in Hamburg.'}]},
  {type:'warn',md:{en:'The reflex to break: <b>adding an English -s</b>. It feels harmless and it is wrong almost every time.<br>„<s>die Buchs</s>“ ✗ → die <b>Bücher</b> · „<s>die Freunds</s>“ ✗ → die <b>Freunde</b> · „<s>die Kinds</s>“ ✗ → die <b>Kinder</b> · „<s>die Haus</s>“ ✗ → die <b>Häuser</b><br>German <b>-s</b> is reserved for imported words and abbreviations: das Auto → Autos, das Hotel → Hotels, das Handy → Handys, das Baby → Babys, das Team → Teams, der Chef → Chefs, die CD → CDs. If the word does not look foreign, do not use -s.<br>Second trap: the plural article is <b>die</b> — but only in the Nominative and Accusative. In the Dative plural it becomes <b>den</b> and the noun takes one more -n: „mit <b>den Büchern</b>“, „mit <b>den Kindern</b>“, „in <b>den Städten</b>“.',
        fa:'واکنشی که باید بشکنی: <b>افزودن ‎-s‎ انگلیسی</b>. بی‌خطر به نظر می‌رسد و تقریباً همیشه غلط است: «die Buchs» ✗ → die <b>Bücher</b>؛ «die Freunds» ✗ → die <b>Freunde</b>. ‎-s‎ آلمانی برای واژه‌های وام‌گرفته و سرواژه‌ها است: Autos، Hotels، Handys، Teams، CDs. اگر واژه بیگانه به نظر نمی‌رسد، ‎-s‎ نگذار. دام دوم: حرف تعریف جمع <b>die</b> است، اما در داتیوِ جمع <b>den</b> می‌شود و اسم یک ‎-n‎ دیگر می‌گیرد: «mit den Büchern».'}},
  {type:'tip',md:{en:'Some nouns exist only in the plural: <b>die Eltern</b> (parents), <b>die Leute</b> (people), <b>die Ferien</b> (school holidays), <b>die Geschwister</b> (siblings) — they take a plural verb: „Die Leute <b>sind</b> freundlich.“ Others exist only in the singular: <b>das Obst</b>, <b>das Gemüse</b>, <b>das Geld</b>, <b>die Information</b> as mass nouns — „Das Obst <b>ist</b> frisch“, and for countable pieces you say „zwei <b>Stück</b> Obst“ or switch to „Informationen“.',
        fa:'برخی اسم‌ها فقط جمع‌اند: <b>die Eltern</b>، <b>die Leute</b>، <b>die Ferien</b>، <b>die Geschwister</b> — و فعل جمع می‌گیرند. برخی فقط مفرد: <b>das Obst</b>، <b>das Gemüse</b>، <b>das Geld</b>.'}},
  {type:'quiz',q:{en:'„ein Buch → zwei ___“',fa:'«ein Buch → zwei ___»'},
   a:'Bücher',o:['Buchs','Buche','Bucher'],
   ex:{en:'<i>Buch</i> is neuter and takes <b>-er plus an Umlaut</b>: die <b>Bücher</b>. The same pattern gives Haus → Häuser, Glas → Gläser, Wort → Wörter. „Buchs“ is the English reflex; „Bucher“ forgets the Umlaut.',
       fa:'<i>Buch</i> خنثی است و <b>‎-er به‌همراه اوملاوت</b> می‌گیرد: die <b>Bücher</b>. همین الگو: Haus → Häuser، Glas → Gläser، Wort → Wörter.'}}
 ]},

/* ============ 11 · modals ============ */
{id:'modals',ic:'🔧',lv:3,sk:'Verbs',
 title:{en:'Modal verbs',fa:'فعل‌های کمکی وجهی'},
 sub:{en:'können, müssen, wollen — and the nicht müssen trap',fa:'können، müssen، wollen — و دام nicht müssen'},
 blocks:[
  {type:'text',md:{en:'Modal verbs do not describe an action — they describe your <b>relationship</b> to an action: can you, must you, may you, do you want to. So they come in pairs with a real verb, and German handles that with the <b>Satzklammer</b> (sentence bracket): the modal takes the normal verb slot in position 2, and the real verb is pushed all the way to the <b>end</b>, unchanged, as an infinitive.<br>„Ich <b>kann</b> gut <b>schwimmen</b>.“ — bracket opens with <i>kann</i>, closes with <i>schwimmen</i>. Everything else lives inside.',
        fa:'فعل وجهی خود کار را توصیف نمی‌کند — <b>نسبت</b> تو را با آن کار توصیف می‌کند: می‌توانی، باید، مجازی، می‌خواهی. پس همیشه با یک فعل واقعی جفت می‌شود و آلمانی این را با <b>کمانهٔ جمله</b> (Satzklammer) اداره می‌کند: فعل وجهی جایگاه دوم را می‌گیرد و فعل واقعی، بی‌تغییر و به‌صورت مصدر، به <b>آخر</b> جمله رانده می‌شود.'}},
  {type:'table',head:['','können (can)','müssen (must)','dürfen (may)'],rows:[
   ['ich','*kann','*muss','*darf'],
   ['du','kannst','musst','darfst'],
   ['er/sie/es','*kann','*muss','*darf'],
   ['wir','können','müssen','dürfen'],
   ['ihr','könnt','müsst','dürft'],
   ['sie/Sie','können','müssen','dürfen']],
   cap:{en:'ich and er/sie/es are identical and take no ending at all — that is the modal signature.',
        fa:'شکل ich و er/sie/es یکسان است و هیچ پایانه‌ای نمی‌گیرد — امضای فعل وجهی همین است.'}},
  {type:'table',head:['','wollen (want)','sollen (should)','möchten (would like)'],rows:[
   ['ich','*will','*soll','*möchte'],
   ['du','willst','sollst','möchtest'],
   ['er/sie/es','*will','*soll','*möchte'],
   ['wir','wollen','sollen','möchten'],
   ['ihr','wollt','sollt','möchtet'],
   ['sie/Sie','wollen','sollen','möchten']],
   cap:{en:'„will“ means want, not will — a famous false friend. And möchten is the polite everyday wollen.',
        fa:'«will» معنای «می‌خواهم» دارد، نه آیندهٔ انگلیسی — دوستِ دروغین معروف. و möchten شکل مؤدبانهٔ روزمرهٔ wollen است.'}},
  {type:'rule',md:{en:'What each one actually claims:<br><b>können</b> — ability or possibility: „Ich kann kochen.“ „Das kann passieren.“<br><b>müssen</b> — a necessity coming from the situation: „Ich muss arbeiten.“<br><b>dürfen</b> — permission granted by someone: „Darf ich rauchen?“<br><b>sollen</b> — an instruction or expectation from <i>someone else</i>: „Der Arzt sagt, ich soll mehr schlafen.“<br><b>wollen</b> — your own will, quite forceful: „Ich will das nicht.“<br><b>möchten</b> — a softened wish, the polite default for orders and requests: „Ich möchte einen Kaffee.“',
        fa:'هر یک چه می‌گوید: <b>können</b> توانایی یا امکان؛ <b>müssen</b> ضرورت برآمده از موقعیت؛ <b>dürfen</b> اجازه از سوی کسی؛ <b>sollen</b> دستور یا انتظار <i>دیگری</i>؛ <b>wollen</b> خواستِ خودت و نسبتاً قاطع؛ <b>möchten</b> خواستِ نرم‌شده و پیش‌فرض مؤدبانه برای سفارش و درخواست.'}},
  {type:'examples',items:[
   {de:'Ich kann leider nicht kommen.',en:'Unfortunately I cannot come.',say:'Ich kann leider nicht kommen.'},
   {de:'Du musst dich beeilen, der Zug fährt gleich.',en:'You have to hurry, the train is about to leave.',say:'Du musst dich beeilen, der Zug fährt gleich.'},
   {de:'Darf ich hier parken?',en:'Am I allowed to park here?',say:'Darf ich hier parken?'},
   {de:'Ich möchte bitte die Rechnung.',en:'I would like the bill, please.',say:'Ich möchte bitte die Rechnung.'},
   {de:'Wir sollen um acht Uhr da sein.',en:'We are supposed to be there at eight.',say:'Wir sollen um acht Uhr da sein.'},
   {de:'Kannst du mir bitte kurz helfen?',en:'Could you help me for a moment, please?',say:'Kannst du mir bitte kurz helfen?'}]},
  {type:'warn',md:{en:'<b>nicht müssen</b> is the trap that changes the meaning of what you say.<br>„Du <b>musst nicht</b> kommen.“ = you <i>do not have to</i> come. It is permission to stay away.<br>„Du <b>darfst nicht</b> kommen.“ = you <i>must not</i> come. It is a prohibition.<br>English „must not“ is <b>nicht dürfen</b>, never <i>nicht müssen</i>. Saying „Du musst nicht rauchen“ to a guest means „feel free not to smoke“, which is not what you meant.<br>Second trap: „Ich <b>will</b> einen Kaffee“ is grammatically perfect and socially blunt — it sounds like a demand. Use „Ich <b>möchte</b> einen Kaffee“ or „Ich <b>hätte gern</b> einen Kaffee“.<br>Third: no <b>zu</b> before the infinitive. „<s>Ich kann zu schwimmen</s>“ ✗ → „Ich kann schwimmen.“ ✓',
        fa:'<b>nicht müssen</b> دامی است که معنای حرفت را عوض می‌کند. «Du musst nicht kommen» = لازم نیست بیایی. «Du darfst nicht kommen» = نباید بیایی. «must not» انگلیسی همیشه <b>nicht dürfen</b> است، هرگز nicht müssen. دام دوم: «Ich will einen Kaffee» دستوری و تند به گوش می‌رسد؛ «Ich möchte» بگو. سوم: پیش از مصدر <b>zu</b> نمی‌آید.'}},
  {type:'tip',md:{en:'Once you have the modal, you can say almost anything with a tiny vocabulary — because the hard verb goes to the end untouched, in its dictionary form. „Ich muss … <b>reservieren</b> / <b>kündigen</b> / <b>umziehen</b>.“ No conjugation needed. Modals are the fastest way to sound fluent at A2.',
        fa:'وقتی فعل وجهی را داشته باشی، با واژگان کم هم می‌توانی تقریباً هر چیزی بگویی — چون فعل سخت، بی‌هیچ تغییری و در شکل فرهنگ‌نامه‌ای، به آخر می‌رود. فعل‌های وجهی سریع‌ترین راهِ روان‌به‌نظر‌رسیدن در سطح A2 هستند.'}},
  {type:'quiz',q:{en:'How do you say „You do not have to pay“ in German?',fa:'«لازم نیست پرداخت کنی» به آلمانی چه می‌شود؟'},
   a:'Du musst nicht bezahlen.',o:['Du darfst nicht bezahlen.','Du kannst nicht bezahlen.','Du sollst nicht bezahlen.'],
   ex:{en:'<b>nicht müssen</b> = no obligation, which is exactly „do not have to“. <i>nicht dürfen</i> would be a ban („you are not allowed to pay“), <i>nicht können</i> an inability, and <i>nicht sollen</i> someone advising you against it.',
       fa:'<b>nicht müssen</b> یعنی الزامی نیست — همان «لازم نیست». <i>nicht dürfen</i> ممنوعیت است، <i>nicht können</i> ناتوانی، و <i>nicht sollen</i> توصیهٔ کسی برخلاف آن.'}}
 ]},

/* ============ 12 · separable ============ */
{id:'separable',ic:'✂️',lv:3,sk:'Verbs',
 title:{en:'Separable & inseparable verbs',fa:'فعل‌های جداشدنی و جدانشدنی'},
 sub:{en:'When the prefix flies to the end — and when it never moves',fa:'کِی پیشوند به آخر می‌پرد و کِی هرگز جابه‌جا نمی‌شود'},
 blocks:[
  {type:'text',md:{en:'German builds new verbs by bolting a small word onto the front: <b>stehen</b> (stand) → <b>aufstehen</b> (get up), <b>kaufen</b> (buy) → <b>einkaufen</b> (go shopping), <b>rufen</b> (call out) → <b>anrufen</b> (phone someone). It is the same trick as English „stand up“, „look after“, „put off“ — except German writes the two parts as one word in the dictionary, then pulls them apart in the sentence. The prefix lands at the very <b>end</b>, forming a bracket around everything else.',
        fa:'آلمانی با چسباندن واژه‌ای کوچک به ابتدای فعل، فعل تازه می‌سازد: <b>stehen</b> → <b>aufstehen</b>، <b>kaufen</b> → <b>einkaufen</b>، <b>rufen</b> → <b>anrufen</b>. همان ترفند «stand up» و «look after» انگلیسی است — با این تفاوت که آلمانی دو بخش را در فرهنگ‌نامه یک واژه می‌نویسد و بعد در جمله از هم جدا می‌کند. پیشوند به <b>آخر</b> می‌رود و دور همه‌چیز کمانه می‌بندد.'}},
  {type:'rule',md:{en:'Which prefixes separate? Use the <b>stress test</b>:<br>• Stress on the <b>prefix</b> → it <b>separates</b>. <b>AUF</b>stehen, <b>EIN</b>kaufen, <b>AN</b>rufen, <b>MIT</b>kommen, <b>AB</b>fahren.<br>• Stress on the <b>stem</b> → it <b>never</b> separates. ver<b>STEH</b>en, be<b>ZAHL</b>en, er<b>ZÄHL</b>en.<br>The inseparable list is short and closed, so just learn it: <b>be-, ge-, er-, ver-, zer-, ent-, emp-, miss-</b>. Everything else that looks like a preposition (auf, ein, an, aus, mit, ab, zu, vor, nach, her, hin) separates.',
        fa:'کدام پیشوندها جدا می‌شوند؟ از <b>آزمون تکیه</b> استفاده کن: تکیه روی <b>پیشوند</b> → <b>جدا می‌شود</b> (AUFstehen، EINkaufen). تکیه روی <b>بُن</b> → <b>هرگز</b> جدا نمی‌شود (verSTEHen، beZAHLen). فهرست جدانشدنی‌ها کوتاه و بسته است: <b>be-، ge-، er-، ver-، zer-، ent-، emp-، miss-</b>. هر پیشوند دیگری که شبیه حرف اضافه است، جدا می‌شود.'}},
  {type:'contrast',cols:[
   {t:'separable: aufstehen',md:{en:'Present: „Ich <b>stehe</b> um sieben <b>auf</b>.“<br>Participle — ge- goes <i>inside</i>: „Ich bin früh <b>aufgestanden</b>.“<br>With zu — zu goes <i>inside</i>: „Es ist schwer, früh <b>aufzustehen</b>.“<br>In a subordinate clause it joins up again: „…, weil ich früh <b>aufstehe</b>.“'}},
   {t:'inseparable: verstehen',md:{en:'Present: „Ich <b>verstehe</b> dich.“ — nothing moves.<br>Participle — <b>no ge-</b> at all: „Ich habe dich <b>verstanden</b>.“<br>With zu — zu stays outside: „Es ist leicht <b>zu verstehen</b>.“<br>In a subordinate clause: „…, weil ich dich <b>verstehe</b>.“ Identical.'}}]},
  {type:'table',head:['Prefix','Flavour','Verb','In a sentence'],rows:[
   ['*auf-','open, up','aufmachen','Ich mache das Fenster *auf.'],
   ['*ein-','in, into','einkaufen','Wir kaufen am Samstag *ein.'],
   ['*an-','at, on, start','anrufen','Er ruft dich später *an.'],
   ['*aus-','out, off','ausgehen','Heute gehen wir *aus.'],
   ['*mit-','along, with','mitkommen','Kommst du *mit?'],
   ['*ab-','away, off','abfahren','Der Zug fährt um acht *ab.'],
   ['*zu-','shut','zumachen','Mach bitte die Tür *zu.'],
   ['*vor-','fore, in front','vorstellen','Ich stelle mich kurz *vor.']],
   cap:{en:'The prefix carries most of the meaning — which is why German saves it for last.',
        fa:'بیشترِ معنا در پیشوند است — و همین است که آلمانی آن را برای آخر نگه می‌دارد.'}},
  {type:'examples',items:[
   {de:'Ich stehe jeden Tag um sieben Uhr auf.',en:'I get up at seven every day.',say:'Ich stehe jeden Tag um sieben Uhr auf.'},
   {de:'Wir kaufen am Samstag im Supermarkt ein.',en:'We do our shopping at the supermarket on Saturday.',say:'Wir kaufen am Samstag im Supermarkt ein.'},
   {de:'Der Zug fährt in fünf Minuten ab.',en:'The train leaves in five minutes.',say:'Der Zug fährt in fünf Minuten ab.'},
   {de:'Machst du bitte das Fenster auf?',en:'Could you open the window, please?',say:'Machst du bitte das Fenster auf?'},
   {de:'Ich rufe dich heute Abend an.',en:'I will call you this evening.',say:'Ich rufe dich heute Abend an.'},
   {de:'Ich habe mich schon vorgestellt.',en:'I have already introduced myself. (ge- inside)',say:'Ich habe mich schon vorgestellt.'}]},
  {type:'warn',md:{en:'The error is simply <b>leaving the prefix attached</b>, because that is what the dictionary showed you:<br>„<s>Ich aufstehe um sieben.</s>“ ✗ → „Ich <b>stehe</b> um sieben <b>auf</b>.“ ✓<br>„<s>Ich anrufe dich morgen.</s>“ ✗ → „Ich <b>rufe</b> dich morgen <b>an</b>.“ ✓<br>And the two places where it goes <i>back</i> together, which learners then overcorrect:<br>• after a modal, the whole infinitive stays whole: „Ich muss früh <b>aufstehen</b>.“ ✓ not „<s>auf stehen</s>“.<br>• in a subordinate clause the verb is at the end anyway, so it rejoins: „…, weil ich früh <b>aufstehe</b>.“ ✓<br>Participle trap: ge- goes <i>inside</i> a separable verb (<b>auf</b>ge<b>standen</b>, <b>ein</b>ge<b>kauft</b>, <b>an</b>ge<b>rufen</b>) and inseparable verbs take <b>no ge- at all</b> (verstanden, bezahlt, erzählt) — „<s>gebezahlt</s>“ ✗.',
        fa:'خطا همین است که <b>پیشوند را چسبیده رها می‌کنی</b>، چون فرهنگ‌نامه همان را نشانت داده: «Ich aufstehe um sieben» ✗ → «Ich <b>stehe</b> um sieben <b>auf</b>» ✓. و دو جایی که پیشوند دوباره می‌چسبد: پس از فعل وجهی («Ich muss früh aufstehen») و در جملهٔ پیرو («…, weil ich früh aufstehe»). در اسم مفعول، ge- <i>داخل</i> فعل جداشدنی می‌رود (aufgestanden) و فعل جدانشدنی <b>هیچ</b> ge- نمی‌گیرد (verstanden).'}},
  {type:'tip',md:{en:'Listening tip: in German the point of the sentence often arrives <b>last</b>. „Ich rufe meine Schwester morgen Abend nach dem Essen …“ — you still do not know whether she is being <i>called</i> (an) or <i>called out to</i> (aus). Train yourself not to stop listening at the verb, because the verb is not finished yet.',
        fa:'نکتهٔ شنیداری: در آلمانی نکتهٔ اصلی جمله غالباً <b>آخر</b> می‌رسد. «Ich rufe meine Schwester morgen Abend …» — هنوز نمی‌دانی an است یا aus. خودت را عادت بده که شنیدن را با رسیدن به فعل تمام نکنی، چون فعل هنوز تمام نشده است.'}},
  {type:'quiz',q:{en:'Which sentence is correct German?',fa:'کدام جمله آلمانیِ درست است؟'},
   a:'Ich rufe dich morgen an.',o:['Ich anrufe dich morgen.','Ich rufe an dich morgen.','Ich dich morgen anrufe.'],
   ex:{en:'<b>anrufen</b> is separable, so <i>rufe</i> takes position 2 and the prefix <b>an</b> goes to the very end, behind everything else. Keeping „anrufe“ together in a main clause is the classic error; putting „an“ directly after the verb is not German either.',
       fa:'<b>anrufen</b> جداشدنی است، پس <i>rufe</i> جایگاه ۲ را می‌گیرد و پیشوند <b>an</b> به آخرِ آخر می‌رود. چسبیده‌نگه‌داشتن «anrufe» در جملهٔ اصلی خطای کلاسیک است.'}}
 ]},

/* ============ 13 · perfekt ============ */
{id:'perfekt',ic:'⏱️',lv:3,sk:'Verbs',
 title:{en:'Perfekt — the spoken past',fa:'ماضی نقلی — گذشتهٔ گفتاری'},
 sub:{en:'haben or sein, plus the participle at the end',fa:'haben یا sein، و اسم مفعول در آخر'},
 blocks:[
  {type:'text',md:{en:'This is how Germans actually talk about the past — in conversation, in chat messages, in emails. It is built from two parts: a <b>helper verb</b> (haben or sein) in the normal verb slot, and the <b>Partizip II</b> at the very end of the sentence. The helper is the part that gets conjugated; the participle never changes its form, no matter who did it.<br>„Ich <b>habe</b> gestern Fußball <b>gespielt</b>.“ Another bracket: helper opens it, participle closes it.',
        fa:'این شکلی است که آلمانی‌زبان‌ها واقعاً از گذشته حرف می‌زنند — در گفت‌وگو، پیام و ایمیل. دو بخش دارد: یک <b>فعل کمکی</b> (haben یا sein) در جایگاه عادی فعل، و <b>اسم مفعول</b> در آخرِ جمله. فعل کمکی صرف می‌شود؛ اسم مفعول هرگز شکلش عوض نمی‌شود، هر که فاعل باشد.'}},
  {type:'table',head:['Verb type','Participle','Example'],rows:[
   ['regular (weak)','*ge- + stem + -t','spielen → *gespielt · machen → *gemacht'],
   ['stem in -t/-d','*ge- + stem + -et','arbeiten → *gearbeitet · warten → *gewartet'],
   ['irregular (strong)','*ge- + stem + -en, often new vowel','sehen → *gesehen · trinken → *getrunken'],
   ['very irregular','learn it whole','nehmen → *genommen · essen → *gegessen'],
   ['ends in -ieren','*no ge-','studieren → *studiert · passieren → *passiert'],
   ['inseparable prefix','*no ge-','verstehen → *verstanden · bezahlen → *bezahlt'],
   ['separable prefix','*ge- goes inside','aufstehen → *aufgestanden · einkaufen → *eingekauft']],
   cap:{en:'The only two groups without ge- are -ieren verbs and inseparable prefixes. Everything else has it somewhere.',
        fa:'تنها دو گروهی که ge- نمی‌گیرند: فعل‌های ‎-ieren‎ و پیشوندهای جدانشدنی. بقیه جایی ge- دارند.'}},
  {type:'steps',items:[
   {en:'Does the verb move the subject <b>from A to B</b>? (gehen, fahren, fliegen, kommen, laufen, reisen, steigen) → <b>sein</b>.',fa:'آیا فعل فاعل را <b>از جایی به جایی</b> می‌برد؟ (gehen، fahren، fliegen، kommen، laufen، reisen) → <b>sein</b>.'},
   {en:'Does it mark a <b>change of state</b>? (aufstehen, einschlafen, aufwachen, werden, wachsen, sterben) → <b>sein</b>.',fa:'آیا <b>تغییر حالت</b> را نشان می‌دهد؟ (aufstehen، einschlafen، aufwachen، werden، wachsen، sterben) → <b>sein</b>.'},
   {en:'Is it <b>sein</b>, <b>bleiben</b> or <b>passieren</b> itself? → <b>sein</b>. („Ich bin da gewesen.“ „Es ist nichts passiert.“)',fa:'آیا خودِ <b>sein</b>، <b>bleiben</b> یا <b>passieren</b> است؟ → <b>sein</b>.'},
   {en:'Does the verb have a <b>direct object</b> (an Accusative)? → <b>haben</b>, always. This beats rule 1: „Ich <b>habe</b> das Auto gefahren.“',fa:'آیا فعل <b>مفعول مستقیم</b> دارد؟ → همیشه <b>haben</b>. این قاعده بر قاعدهٔ ۱ می‌چربد: «Ich <b>habe</b> das Auto gefahren.»'},
   {en:'Anything else at all → <b>haben</b>. Roughly 90% of verbs land here.',fa:'هر چیز دیگری → <b>haben</b>. حدود ۹۰٪ فعل‌ها اینجا می‌افتند.'}]},
  {type:'contrast',cols:[
   {t:'fahren with sein — a journey',md:{en:'„Ich <b>bin</b> nach Berlin gefahren.“<br>„Wir <b>sind</b> mit dem Zug gefahren.“<br>No object. The subject itself went somewhere.'}},
   {t:'fahren with haben — an object',md:{en:'„Ich <b>habe</b> den Lkw gefahren.“ — I drove the truck.<br>„Er <b>hat</b> mich nach Hause gefahren.“<br>There is an Accusative object, so the verb behaves like any ordinary action verb: haben.'}}]},
  {type:'examples',items:[
   {de:'Was hast du am Wochenende gemacht?',en:'What did you do at the weekend?',say:'Was hast du am Wochenende gemacht?'},
   {de:'Ich habe meine Schlüssel verloren.',en:'I have lost my keys.',say:'Ich habe meine Schlüssel verloren.'},
   {de:'Wir sind mit dem Zug nach Hamburg gefahren.',en:'We took the train to Hamburg.',say:'Wir sind mit dem Zug nach Hamburg gefahren.'},
   {de:'Sie ist heute sehr früh aufgestanden.',en:'She got up very early today.',say:'Sie ist heute sehr früh aufgestanden.'},
   {de:'Hast du schon gegessen?',en:'Have you eaten yet?',say:'Hast du schon gegessen?'},
   {de:'Ich habe das nicht verstanden — kannst du das wiederholen?',en:'I did not understand that — can you repeat it?',say:'Ich habe das nicht verstanden.'}]},
  {type:'warn',md:{en:'Two traps, one grammatical and one that lives in your English instincts.<br>1. <b>haben where it should be sein.</b> „<s>Ich habe nach Berlin gefahren.</s>“ ✗ → „Ich <b>bin</b> nach Berlin gefahren.“ ✓ „<s>Ich habe früh aufgestanden.</s>“ ✗ → „Ich <b>bin</b> früh aufgestanden.“ ✓ Movement and change of state take <b>sein</b>.<br>2. <b>The tense mismatch.</b> In English „I have seen him yesterday“ is wrong — a finished past time forces the simple past. German has no such restriction: „Ich <b>habe</b> ihn gestern gesehen“ is not only allowed, it is the <i>normal</i> way to say it. So do not avoid the Perfekt with <i>gestern, letzte Woche, 2019</i> — and do not reach for „Ich sah ihn gestern“, which sounds like a novel. Trust the Perfekt in speech.',
        fa:'دو دام، یکی دستوری و یکی در غریزهٔ انگلیسی‌ات. ۱) <b>haben به‌جای sein</b>: «Ich habe nach Berlin gefahren» ✗ → «Ich <b>bin</b> nach Berlin gefahren» ✓. حرکت و تغییر حالت <b>sein</b> می‌گیرند. ۲) <b>ناهم‌خوانی زمان‌ها</b>: در انگلیسی «I have seen him yesterday» غلط است، اما در آلمانی «Ich habe ihn gestern gesehen» شکل <i>طبیعی</i> است. پس با gestern و letzte Woche هم از ماضی نقلی نترس.'}},
  {type:'tip',md:{en:'Never learn a participle alone. Learn the <b>three-part chunk</b> with its helper baked in: „fahren – <b>ist</b> gefahren“, „essen – <b>hat</b> gegessen“, „aufstehen – <b>ist</b> aufgestanden“, „bleiben – <b>ist</b> geblieben“. Then the haben/sein question never comes up again, because you learnt the answer with the word.',
        fa:'هرگز اسم مفعول را تنها یاد نگیر. <b>سه‌گانه</b> را با فعل کمکی‌اش حفظ کن: «fahren – <b>ist</b> gefahren»، «essen – <b>hat</b> gegessen»، «bleiben – <b>ist</b> geblieben». آن‌وقت پرسش haben/sein دیگر هرگز پیش نمی‌آید.'}},
  {type:'quiz',q:{en:'„Wir ___ letztes Jahr nach Italien geflogen.“',fa:'«Wir ___ letztes Jahr nach Italien geflogen.»'},
   a:'sind',o:['haben','waren','hatten'],
   ex:{en:'<b>fliegen</b> here is movement from A to B with no object, so the helper is <b>sein</b>: „Wir <b>sind</b> … geflogen.“ Note that „letztes Jahr“ does not force a different tense — in German the Perfekt is fine with a finished time expression.',
       fa:'<b>fliegen</b> اینجا حرکت از جایی به جایی و بی‌مفعول است، پس فعل کمکی <b>sein</b> است. و «letztes Jahr» زمان دیگری را الزامی نمی‌کند — در آلمانی ماضی نقلی با قید زمان گذشته هم درست است.'}}
 ]},

/* ============ 14 · praeteritum ============ */
{id:'praeteritum',ic:'⏳',lv:4,sk:'Verbs',
 title:{en:'Präteritum — the written past',fa:'گذشتهٔ ساده — گذشتهٔ نوشتاری'},
 sub:{en:'The tense you read constantly and say rarely',fa:'زمانی که مدام می‌خوانی و کم می‌گویی'},
 blocks:[
  {type:'text',md:{en:'The Präteritum means exactly the same thing as the Perfekt — „I played“, „she went“. The difference is not time, it is <b>register</b>. Perfekt belongs to speech; Präteritum belongs to writing: novels, news reports, histories, fairy tales. The one group of verbs that ignores this split is the group you use most: <b>sein, haben, werden, wissen</b> and the modals are said in the Präteritum even in conversation, because „ich bin gewesen“ is just clumsier than „ich war“.',
        fa:'گذشتهٔ ساده دقیقاً همان معنای ماضی نقلی را دارد. تفاوت در زمان نیست، در <b>سَبک</b> است: ماضی نقلی به گفتار تعلق دارد و گذشتهٔ ساده به نوشتار — رمان، خبر، تاریخ، افسانه. تنها گروهی که این تقسیم را نادیده می‌گیرد، همان پرکاربردترین‌هاست: <b>sein، haben، werden، wissen</b> و فعل‌های وجهی در گفتار هم با گذشتهٔ ساده می‌آیند.'}},
  {type:'table',head:['','spielen (weak)','gehen (strong)'],rows:[
   ['ich','spiel*te','*ging'],
   ['du','spiel*test','ging*st'],
   ['er/sie/es','spiel*te','*ging'],
   ['wir','spiel*ten','ging*en'],
   ['ihr','spiel*tet','ging*t'],
   ['sie/Sie','spiel*ten','ging*en']],
   cap:{en:'Weak verbs insert -te-. Strong verbs change the vowel instead — and ich/er take no ending at all.',
        fa:'فعل‌های باقاعده ‎-te-‎ می‌گیرند. فعل‌های بی‌قاعده مصوت را عوض می‌کنند — و ich/er هیچ پایانه‌ای ندارند.'}},
  {type:'table',head:['infinitive','Präteritum (er)','Perfekt'],rows:[
   ['*sein','*war','ist gewesen'],
   ['*haben','*hatte','hat gehabt'],
   ['*werden','*wurde','ist geworden'],
   ['*wissen','*wusste','hat gewusst'],
   ['*können','*konnte','hat gekonnt'],
   ['*müssen','*musste','hat gemusst'],
   ['gehen','ging','ist gegangen'],
   ['kommen','kam','ist gekommen'],
   ['fahren','fuhr','ist gefahren'],
   ['sehen','sah','hat gesehen'],
   ['essen','aß','hat gegessen'],
   ['geben','gab','hat gegeben'],
   ['sprechen','sprach','hat gesprochen'],
   ['nehmen','nahm','hat genommen']],
   cap:{en:'The six starred verbs you really do say out loud. The rest you mostly read.',
        fa:'شش فعل ستاره‌دار را واقعاً به زبان می‌آوری. بقیه را بیشتر می‌خوانی.'}},
  {type:'steps',items:[
   {en:'Speaking, chatting, writing an email to a friend? → <b>Perfekt</b>.',fa:'در گفتار، پیام یا ایمیل دوستانه؟ → <b>ماضی نقلی</b>.'},
   {en:'But the verb is <b>sein, haben, werden, wissen</b> or a modal? → <b>Präteritum</b>, even when speaking: „Ich <b>war</b> krank“, „Er <b>hatte</b> keine Zeit“, „Ich <b>konnte</b> nicht kommen“.',fa:'اما فعل <b>sein، haben، werden، wissen</b> یا وجهی است؟ → <b>گذشتهٔ ساده</b>، حتی در گفتار.'},
   {en:'Writing a story, a report, a news article, an exam text? → <b>Präteritum</b> throughout.',fa:'داستان، گزارش، خبر یا متن آزمون می‌نویسی؟ → سراسر <b>گذشتهٔ ساده</b>.'},
   {en:'Telling a connected sequence of past events, even aloud? → Präteritum is also fine and sounds more polished: „Dann <b>kam</b> er herein und <b>sagte</b>…“',fa:'زنجیره‌ای از رویدادهای گذشته را، حتی شفاهی، تعریف می‌کنی؟ → گذشتهٔ ساده هم درست است و پرداخته‌تر به گوش می‌رسد.'},
   {en:'In the south of Germany and in Austria, speakers lean on the Perfekt even harder. In the north the Präteritum appears more often in speech.',fa:'در جنوب آلمان و اتریش گویشوران بیشتر به ماضی نقلی تکیه می‌کنند؛ در شمال، گذشتهٔ ساده در گفتار بیشتر دیده می‌شود.'}]},
  {type:'contrast',cols:[
   {t:'Perfekt — you say it',md:{en:'„Ich <b>habe</b> gestern zu viel <b>gegessen</b>.“<br>„<b>Hast</b> du den Film schon <b>gesehen</b>?“<br>„Wir <b>sind</b> am Samstag ins Kino <b>gegangen</b>.“<br>Natural in any conversation.'}},
   {t:'Präteritum — you read it',md:{en:'„Er <b>öffnete</b> die Tür und <b>sah</b> niemanden.“<br>„Die Regierung <b>beschloss</b> neue Regeln.“<br>„Es <b>war</b> einmal ein König…“<br>Narrative, press, fiction. In a chat message it sounds like a storybook.'}}]},
  {type:'examples',items:[
   {de:'Ich war gestern krank und konnte nicht arbeiten.',en:'I was ill yesterday and could not work.',say:'Ich war gestern krank und konnte nicht arbeiten.'},
   {de:'Er hatte damals noch kein Auto.',en:'He did not have a car back then.',say:'Er hatte damals noch kein Auto.'},
   {de:'Als ich klein war, wohnten wir in Hamburg.',en:'When I was small we lived in Hamburg.',say:'Als ich klein war, wohnten wir in Hamburg.'},
   {de:'Es gab keinen Kaffee mehr, also tranken wir Tee.',en:'There was no coffee left, so we drank tea.',say:'Es gab keinen Kaffee mehr, also tranken wir Tee.'},
   {de:'Ich wusste nicht, dass du auch kommst.',en:'I did not know that you were coming too.',say:'Ich wusste nicht, dass du auch kommst.'},
   {de:'Tut mir leid, ich musste noch arbeiten.',en:'Sorry, I still had to work.',say:'Tut mir leid, ich musste noch arbeiten.'}]},
  {type:'warn',md:{en:'The giveaway mistake runs in <b>both</b> directions.<br>• Präteritum where speech wants Perfekt: „<s>Gestern aß ich Pizza</s>“ in a WhatsApp message reads like a fairy tale → „Gestern <b>habe</b> ich Pizza <b>gegessen</b>.“ Same with „ich ging“, „ich sah“, „ich kaufte“ — grammatically perfect, socially odd.<br>• Perfekt where the Präteritum is the fixed habit: „<s>Ich bin gestern krank gewesen</s>“ is understandable but clumsy → „Ich <b>war</b> gestern krank.“ And „<s>Ich habe nicht kommen können</s>“ → „Ich <b>konnte</b> nicht kommen.“<br>Easy policy: <b>war, hatte, wurde, wusste, konnte, musste, wollte, durfte, sollte</b> in speech; <b>Perfekt</b> for everything else.',
        fa:'خطای افشاکننده در <b>هر دو</b> جهت رخ می‌دهد. گذشتهٔ ساده جایی که گفتار ماضی نقلی می‌خواهد: «Gestern aß ich Pizza» در پیام، لحن افسانه دارد → «Gestern habe ich Pizza gegessen». و ماضی نقلی جایی که عادت ثابت گذشتهٔ ساده است: «Ich bin gestern krank gewesen» → «Ich <b>war</b> gestern krank». سیاست ساده: <b>war, hatte, wurde, wusste, konnte, musste</b> در گفتار؛ ماضی نقلی برای بقیه.'}},
  {type:'tip',md:{en:'For reading, you do not need to <i>produce</i> these forms — you need to <i>recognise</i> them. A strong Präteritum is almost always a familiar verb with a different vowel: <b>a, i, o, u</b> where the infinitive had <b>e</b> or <b>ei</b>. gab = geben, sprach = sprechen, schrieb = schreiben, zog = ziehen, trug = tragen. Guess the infinitive from the consonants and you will be right.',
        fa:'برای خواندن لازم نیست این شکل‌ها را <i>بسازی</i> — باید <i>بشناسی</i>. گذشتهٔ سادهٔ بی‌قاعده تقریباً همیشه فعلی آشنا با مصوتی دیگر است: gab = geben، sprach = sprechen، schrieb = schreiben، trug = tragen. از همخوان‌ها مصدر را حدس بزن.'}},
  {type:'quiz',q:{en:'You are writing a message to a friend: „Yesterday I ate pizza.“',fa:'به دوستی پیام می‌دهی: «دیروز پیتزا خوردم.»'},
   a:'Gestern habe ich Pizza gegessen.',o:['Gestern aß ich Pizza.','Gestern ich habe Pizza gegessen.','Gestern esse ich Pizza.'],
   ex:{en:'In speech and messages German uses the <b>Perfekt</b>: „habe … gegessen“. „Gestern aß ich Pizza“ is correct Präteritum but belongs in a novel. The third option keeps English word order (verb must be second), and the fourth is present tense.',
       fa:'در گفتار و پیام، آلمانی از <b>ماضی نقلی</b> استفاده می‌کند. «Gestern aß ich Pizza» گذشتهٔ سادهٔ درستی است اما جایش در رمان است. گزینهٔ سوم ترتیب انگلیسی را نگه داشته و گزینهٔ چهارم زمان حال است.'}}
 ]},

/* ============ 15 · prepositions ============ */
{id:'prepositions',ic:'🧭',lv:4,sk:'Prepositions',
 title:{en:'Prepositions & cases',fa:'حروف اضافه و حالت‌ها'},
 sub:{en:'Which case follows — and why you cannot translate them',fa:'چه حالتی می‌آید — و چرا نمی‌توان ترجمه‌شان کرد'},
 blocks:[
  {type:'text',md:{en:'Every German preposition <b>forces a case</b> on the noun that follows it. This is not a style choice and it is not negotiable: <b>für</b> always takes Accusative, <b>mit</b> always takes Dative, whatever the sentence means. So a preposition is really two pieces of information — the meaning, and the case — and you have to learn both together or the word is useless to you.<br>There are three groups: always-Accusative, always-Dative, and the two-way group that switches depending on whether you are describing <i>movement</i> or <i>position</i>.',
        fa:'هر حرف اضافهٔ آلمانی <b>یک حالت را بر اسم بعدی تحمیل می‌کند</b>. این انتخاب سلیقه‌ای نیست و قابل مذاکره هم نیست: <b>für</b> همیشه آکوزاتیو می‌گیرد و <b>mit</b> همیشه داتیو. پس هر حرف اضافه در واقع دو اطلاع است — معنا و حالت — و باید هر دو را با هم یاد بگیری. سه گروه وجود دارد: همیشه‌آکوزاتیو، همیشه‌داتیو، و گروه دوحالته.'}},
  {type:'table',head:['always Akkusativ','always Dativ','two-way (Akk or Dat)'],rows:[
   ['*durch (through)','*aus (out of, from)','*in (in, into)'],
   ['*für (for)','*bei (at, near)','*an (at, onto)'],
   ['*gegen (against)','*mit (with)','*auf (on, onto)'],
   ['*ohne (without)','*nach (after, to)','*über (over, above)'],
   ['*um (around, at)','*seit (since, for)','*unter (under)'],
   ['*bis (until)','*von (from, of)','*vor (in front of)'],
   ['*entlang (along)','*zu (to)','*hinter (behind)'],
   ['—','*gegenüber (opposite)','*neben / zwischen']],
   cap:{en:'The Dative column is the one to chant: aus-bei-mit-nach-seit-von-zu.',
        fa:'ستون داتیو را مثل ذکر تکرار کن: aus-bei-mit-nach-seit-von-zu.'}},
  {type:'rule',md:{en:'The two-way group is decided by a single question:<br><b>wohin?</b> (where to — movement <i>into</i> a new place) → <b>Akkusativ</b><br><b>wo?</b> (where — position, no change of place) → <b>Dativ</b><br>„Ich gehe <b>in die</b> Küche.“ (wohin? → Akk) · „Ich bin <b>in der</b> Küche.“ (wo? → Dat)<br>„Ich hänge das Bild <b>an die</b> Wand.“ · „Das Bild hängt <b>an der</b> Wand.“<br>Careful: it is not whether <i>you</i> are moving, but whether the <b>place changes</b>. „Ich laufe <b>im</b> Park“ is Dative — the running happens inside the park and never leaves it.',
        fa:'گروه دوحالته با یک پرسش تعیین می‌شود: <b>wohin?</b> (به کجا — حرکت <i>به درون</i> جای تازه) → <b>آکوزاتیو</b>؛ <b>wo?</b> (کجا — جایگاه، بی تغییر مکان) → <b>داتیو</b>. دقت کن: ملاک این نیست که <i>تو</i> حرکت می‌کنی، بلکه این است که <b>مکان عوض می‌شود</b> یا نه. «Ich laufe <b>im</b> Park» داتیو است، چون دویدن درون پارک می‌مانَد.'}},
  {type:'table',head:['Long form','Contraction','Example'],rows:[
   ['in dem','*im','*im Kino, im Bus, im Januar'],
   ['in das','*ins','*ins Kino, ins Bett'],
   ['an dem','*am','*am Bahnhof, am Montag'],
   ['an das','*ans','*ans Meer, ans Telefon'],
   ['zu dem','*zum','*zum Arzt, zum Bahnhof'],
   ['zu der','*zur','*zur Arbeit, zur Schule'],
   ['bei dem','*beim','*beim Essen, beim Arzt'],
   ['von dem','*vom','*vom Bahnhof, vom Chef']],
   cap:{en:'These are not optional shortcuts — Germans say im and zum, not „in dem“ and „zu dem“.',
        fa:'این‌ها میان‌بُرهای اختیاری نیستند — آلمانی‌زبان‌ها im و zum می‌گویند، نه «in dem» و «zu dem».'}},
  {type:'examples',items:[
   {de:'Ich fahre mit dem Bus zur Arbeit.',en:'I take the bus to work. (mit + Dativ, zu + Dativ)',say:'Ich fahre mit dem Bus zur Arbeit.'},
   {de:'Das Geschenk ist für dich.',en:'The present is for you. (für + Akkusativ)',say:'Das Geschenk ist für dich.'},
   {de:'Wir gehen heute Abend ins Kino.',en:'We are going to the cinema tonight. (wohin → Akk)',say:'Wir gehen heute Abend ins Kino.'},
   {de:'Der Schlüssel liegt auf dem Tisch.',en:'The key is on the table. (wo → Dativ)',say:'Der Schlüssel liegt auf dem Tisch.'},
   {de:'Seit einem Jahr lerne ich Deutsch.',en:'I have been learning German for a year. (seit + Dativ)',say:'Seit einem Jahr lerne ich Deutsch.'},
   {de:'Ohne meinen Kaffee funktioniere ich morgens nicht.',en:'Without my coffee I do not function in the morning.',say:'Ohne meinen Kaffee funktioniere ich morgens nicht.'}]},
  {type:'warn',md:{en:'The real trap is not the case — it is <b>translating the English preposition</b>. The two languages carve up space and time differently, and a literal translation is wrong far more often than it is right:<br>„on the bus“ → <b>im</b> Bus (not „auf“) · „at the weekend“ → <b>am</b> Wochenende · „in the photo“ → <b>auf</b> dem Foto · „on television“ → <b>im</b> Fernsehen<br>„to Germany“ → <b>nach</b> Deutschland · „to the doctor“ → <b>zum</b> Arzt · „to the cinema“ → <b>ins</b> Kino — three different words for one English „to“.<br>Worst of all, verbs come with their own fixed preposition, and it is rarely the English one:<br>„I am waiting <b>for</b> you“ → „Ich warte <b>auf</b> dich.“ · „interested <b>in</b>“ → „sich interessieren <b>für</b>“ · „depends <b>on</b>“ → „hängt <b>von</b> … ab“ · „think <b>about</b>“ → „denken <b>an</b>“.<br>Learn these as whole chunks — <b>warten auf + Akkusativ</b> — never as a preposition plus a guess.',
        fa:'دام اصلی حالت نیست — <b>ترجمهٔ حرف اضافهٔ انگلیسی</b> است. دو زبان مکان و زمان را جور دیگری تقسیم می‌کنند: «on the bus» → <b>im</b> Bus؛ «at the weekend» → <b>am</b> Wochenende؛ «in the photo» → <b>auf</b> dem Foto. و بدتر از همه، فعل‌ها حرف اضافهٔ ثابت خود را دارند که کم‌تر با انگلیسی می‌خواند: «warten <b>auf</b>»، «sich interessieren <b>für</b>»، «denken <b>an</b>». این‌ها را یکپارچه یاد بگیر.'}},
  {type:'tip',md:{en:'Two chants carry most of the work. Dative: <b>aus – bei – mit – nach – seit – von – zu</b>. Accusative: <b>durch – für – gegen – ohne – um</b>. Say each list in one breath, in that order, until it is automatic. Anything not on either list is almost certainly a two-way preposition, and then you only have to ask <i>wohin</i> or <i>wo</i>.',
        fa:'دو ذکر بیشترِ کار را انجام می‌دهد. داتیو: <b>aus – bei – mit – nach – seit – von – zu</b>. آکوزاتیو: <b>durch – für – gegen – ohne – um</b>. هر فهرست را در یک نفس و به همین ترتیب بگو تا خودکار شود. هر چه در این دو فهرست نباشد، تقریباً مطمئناً دوحالته است.'}},
  {type:'quiz',q:{en:'„Ich warte schon zwanzig Minuten ___ den Bus.“',fa:'«Ich warte schon zwanzig Minuten ___ den Bus.»'},
   a:'auf',o:['für','an','über'],
   ex:{en:'<b>warten auf + Akkusativ</b> is a fixed pair, and you can see the Accusative in <i>den</i> Bus. English „wait for“ pushes you towards <i>für</i>, which is the trap — <i>für</i> would mean the waiting was done on the bus’s behalf.',
       fa:'<b>warten auf + آکوزاتیو</b> جفت ثابتی است، و آکوزاتیو را در <i>den</i> Bus می‌بینی. «wait for» انگلیسی تو را به‌سوی <i>für</i> می‌راند و همین دام است.'}}
 ]},

/* ============ 16 · adjektiv ============ */
{id:'adjektiv',ic:'🎨',lv:4,sk:'Adjectives',
 title:{en:'Adjective endings',fa:'پایانهٔ صفت'},
 sub:{en:'Three tables, or one principle you can actually use',fa:'سه جدول، یا یک اصل که به‌کار می‌آید'},
 blocks:[
  {type:'text',md:{en:'An adjective standing <b>before</b> a noun must carry an ending. The reason is the same one behind the whole case system: German insists that the gender and case be <b>signalled</b> somewhere in the noun phrase. If the article already does that job clearly, the adjective can relax and take a weak, uninformative ending. If the article is missing, or too vague to help, the adjective has to carry the signal itself and takes the full der-ending.<br>That is the whole logic. The three tables below are just that one idea written out.',
        fa:'صفتی که <b>پیش</b> از اسم می‌آید باید پایانه بگیرد. دلیلش همان منطق کل نظام حالت است: آلمانی اصرار دارد که جنس و حالت جایی در گروه اسمی <b>علامت‌گذاری</b> شود. اگر حرف تعریف این کار را روشن انجام دهد، صفت می‌تواند پایانهٔ ضعیف و کم‌اطلاع بگیرد. اگر حرف تعریف نباشد یا مبهم باشد، صفت باید خودش علامت را حمل کند و پایانهٔ کامل der را می‌گیرد. تمام منطق همین است.'}},
  {type:'rule',md:{en:'The one-signal principle, applied:<br>• After <b>der, die, das, dieser, jeder, welcher, alle</b> — the article is fully informative → <b>weak</b> endings, only <b>-e</b> or <b>-en</b>.<br>• After <b>ein, kein, mein, dein, sein, ihr, unser</b> — informative <i>except</i> in three slots (masculine Nominative, neuter Nominative, neuter Accusative), where „ein“ tells you nothing → there, and only there, the adjective jumps in with <b>-er / -es</b>.<br>• With <b>no article at all</b> — nobody else can do it → the adjective takes the <b>der-endings</b>: guter, gute, gutes, gute.',
        fa:'اصل «یک علامت» در عمل: پس از <b>der، die، das، dieser، jeder، welcher، alle</b> حرف تعریف کاملاً گویاست → پایانهٔ <b>ضعیف</b>، تنها <b>‎-e</b> یا <b>‎-en</b>. پس از <b>ein، kein، mein…</b> گویاست <i>مگر</i> در سه خانه (مذکرِ نهادی، خنثیِ نهادی، خنثیِ مفعولی) که «ein» چیزی نمی‌گوید → همان‌جا صفت با <b>‎-er / -es</b> وارد می‌شود. <b>بی هیچ حرف تعریفی</b> → صفت پایانهٔ der را می‌گیرد.'}},
  {type:'table',head:['after der-word','mask.','fem.','neut.','Plural'],rows:[
   ['Nominativ','*-e','*-e','*-e','-en'],
   ['Akkusativ','-en','*-e','*-e','-en'],
   ['Dativ','-en','-en','-en','-en'],
   ['Genitiv','-en','-en','-en','-en']],
   cap:{en:'„Weak“ endings: four -e cells, and -en everywhere else. der rote Apfel · den roten Apfel · dem roten Apfel.',
        fa:'پایانه‌های «ضعیف»: چهار خانهٔ ‎-e‎ و بقیه ‎-en‎.'}},
  {type:'table',head:['after ein-word','mask.','fem.','neut.','Plural'],rows:[
   ['Nominativ','*-er','-e','*-es','-en'],
   ['Akkusativ','-en','-e','*-es','-en'],
   ['Dativ','-en','-en','-en','-en'],
   ['Genitiv','-en','-en','-en','-en']],
   cap:{en:'Identical to the table above except the three starred cells — ein guter Film, ein gutes Buch.',
        fa:'دقیقاً مثل جدول بالا، جز سه خانهٔ ستاره‌دار — ein guter Film، ein gutes Buch.'}},
  {type:'table',head:['no article','mask.','fem.','neut.','Plural'],rows:[
   ['Nominativ','*-er','*-e','*-es','*-e'],
   ['Akkusativ','-en','*-e','*-es','*-e'],
   ['Dativ','*-em','*-er','*-em','-en'],
   ['Genitiv','-en','*-er','-en','*-er']],
   cap:{en:'Compare these with der/die/das/dem/der — they are the same letters. guter Kaffee · mit kaltem Wasser.',
        fa:'این‌ها را با der/die/das/dem/der بسنج — همان حروف‌اند. guter Kaffee · mit kaltem Wasser.'}},
  {type:'examples',items:[
   {de:'Das ist ein guter Film.',en:'That is a good film. (masc. Nom. after ein → -er)',say:'Das ist ein guter Film.'},
   {de:'Ich suche eine günstige Wohnung.',en:'I am looking for an affordable flat. (fem. Akk. → -e)',say:'Ich suche eine günstige Wohnung.'},
   {de:'Sie trägt einen schwarzen Mantel.',en:'She is wearing a black coat. (masc. Akk. → -en)',say:'Sie trägt einen schwarzen Mantel.'},
   {de:'Ich fahre mit dem neuen Fahrrad.',en:'I ride the new bike. (Dativ → -en)',say:'Ich fahre mit dem neuen Fahrrad.'},
   {de:'Wir haben frisches Brot gekauft.',en:'We bought fresh bread. (neut. Akk., no article → -es)',say:'Wir haben frisches Brot gekauft.'},
   {de:'Kalter Kaffee schmeckt furchtbar.',en:'Cold coffee tastes awful. (masc. Nom., no article → -er)',say:'Kalter Kaffee schmeckt furchtbar.'}]},
  {type:'warn',md:{en:'Two things go wrong, and the second one is the bigger prize.<br>1. <b>Guessing in the three ein-slots.</b> This is where learners produce „<s>ein gute Film</s>“ ✗ or „<s>ein gut Film</s>“ ✗ → „ein <b>guter</b> Film“ ✓; and „<s>ein gute Buch</s>“ ✗ → „ein <b>gutes</b> Buch“ ✓. If you learn nothing else, learn those two shapes: <b>ein guter …</b> (masc.) and <b>ein gutes …</b> (neut.).<br>2. <b>Adding an ending where none belongs.</b> After <b>sein, werden, bleiben</b> the adjective stands alone and takes <b>no ending at all</b>:<br>„Der Film ist <b>gut</b>.“ ✓ — never „<s>ist guter</s>“ ✗<br>„Die Wohnung ist zu <b>teuer</b>.“ ✓ · „Das Wetter wird <b>besser</b>.“ ✓<br>So the rule has a hard boundary: endings only <i>in front of</i> a noun. Behind the verb, the adjective is bare.',
        fa:'دو چیز خراب می‌شود و دومی مهم‌تر است. ۱) <b>حدس‌زدن در سه خانهٔ ein</b>: «ein gute Film» ✗ → «ein <b>guter</b> Film» ✓؛ «ein gute Buch» ✗ → «ein <b>gutes</b> Buch» ✓. ۲) <b>افزودن پایانه آنجا که جایش نیست</b>: پس از sein، werden و bleiben صفت تنها می‌ایستد و <b>هیچ</b> پایانه‌ای نمی‌گیرد: «Der Film ist <b>gut</b>» ✓، نه «ist guter» ✗. قاعده مرز سختی دارد: پایانه فقط <i>پیش از</i> اسم.'}},
  {type:'tip',md:{en:'The statistics are on your side. Count the cells: more than half of all three tables is simply <b>-en</b>. So the working shortcut is — <b>if it is Dative, Genitive or plural, say -en</b>, and you will be right almost every time. That leaves you only the Nominative and Accusative singular to think about, which is six cells, not forty-eight.',
        fa:'آمار به سودت است. خانه‌ها را بشمار: بیش از نیمِ هر سه جدول فقط <b>‎-en</b> است. پس میان‌بُر کاری این است: <b>اگر داتیو، اضافی یا جمع بود، ‎-en‎ بگو</b> — و تقریباً همیشه درست می‌گویی. آن‌وقت فقط نهادی و مفعولیِ مفرد می‌ماند: شش خانه، نه چهل‌وهشت.'}},
  {type:'quiz',q:{en:'„Das ist ___ Film. Du musst ihn sehen!“ (ein + gut)',fa:'«Das ist ___ Film. Du musst ihn sehen!» (ein + gut)'},
   a:'ein guter',o:['ein gute','ein gutes','einen guten'],
   ex:{en:'After <b>sein</b> the phrase stays Nominative, and <i>Film</i> is masculine. „ein“ gives no gender signal in the masculine Nominative, so the adjective supplies it: <b>guter</b>. Compare „ein <b>gutes</b> Buch“ (neuter) and „Ich kenne <b>einen guten</b> Film“ (Accusative).',
       fa:'پس از <b>sein</b> گروه اسمی نهادی می‌ماند و <i>Film</i> مذکر است. «ein» در مذکرِ نهادی علامت جنس نمی‌دهد، پس صفت آن را تأمین می‌کند: <b>guter</b>. مقایسه کن: «ein <b>gutes</b> Buch» و «Ich kenne <b>einen guten</b> Film».'}}
 ]},

/* ============ 17 · komparativ ============ */
{id:'komparativ',ic:'📏',lv:4,sk:'Adjectives',
 title:{en:'Comparative & superlative',fa:'صفت برتر و برترین'},
 sub:{en:'größer als — and never „mehr groß“',fa:'größer als — و هرگز «mehr groß»'},
 blocks:[
  {type:'text',md:{en:'English has two systems: short words take <i>-er</i> („bigger“) and long ones take <i>more</i> („more interesting“). <b>German has only the first one.</b> Every adjective, however long, takes <b>-er</b> for the comparative and <b>-st</b> for the superlative — <i>interessanter</i>, <i>am interessantesten</i>. There is no „more“ construction to fall back on, which makes German simpler than English here, as soon as you stop looking for the escape route.',
        fa:'انگلیسی دو نظام دارد: واژه‌های کوتاه ‎-er‎ می‌گیرند و بلندها «more». <b>آلمانی فقط نظام اول را دارد.</b> هر صفتی، هر چقدر بلند، برای برتر <b>‎-er</b> و برای برترین <b>‎-st</b> می‌گیرد — <i>interessanter</i>، <i>am interessantesten</i>. هیچ ساختِ «more» وجود ندارد، و همین آلمانی را اینجا از انگلیسی ساده‌تر می‌کند.'}},
  {type:'table',head:['adjective','comparative','superlative'],rows:[
   ['klein','kleiner','am kleinsten'],
   ['interessant','interessanter','am interessantesten'],
   ['groß','gr*ößer','am gr*ößten'],
   ['alt','*älter','am *ältesten'],
   ['jung','j*ünger','am j*üngsten'],
   ['kurz','k*ürzer','am k*ürzesten'],
   ['teuer','*teurer','am teuersten'],
   ['hoch','*höher','am höchsten'],
   ['nah','*näher','am *nächsten'],
   ['gut','*besser','*am besten'],
   ['viel','*mehr','*am meisten'],
   ['gern','*lieber','*am liebsten']],
   cap:{en:'The last three are the irregulars — and they are the ones you need every day.',
        fa:'سه ردیف آخر بی‌قاعده‌اند — و همان‌هایی هستند که هر روز لازم داری.'}},
  {type:'rule',md:{en:'Three spelling details that cover nearly all the odd forms:<br>1. Short one-syllable adjectives usually take an <b>Umlaut</b>: alt→älter, jung→jünger, kalt→kälter, warm→wärmer, lang→länger, kurz→kürzer, stark→stärker, groß→größer. But <i>not</i> bunt, froh, klar, voll, wahr, schlank, flach, laut.<br>2. Adjectives ending in <b>-t, -d, -s, -ß, -z</b> insert an e in the superlative: am ält<b>e</b>sten, am kürz<b>e</b>sten, am heiß<b>e</b>sten.<br>3. Adjectives ending in <b>-er, -el</b> drop that e in the comparative: teuer→t<b>eu</b>rer, dunkel→dun<b>k</b>ler.',
        fa:'سه نکتهٔ املایی که تقریباً همهٔ شکل‌های عجیب را پوشش می‌دهد: ۱) صفت‌های کوتاهِ یک‌هجایی معمولاً <b>اوملاوت</b> می‌گیرند (alt→älter، warm→wärmer)، اما bunt، froh، klar، voll و wahr نه. ۲) صفت‌های پایان‌یافته به <b>‎-t، -d، -s، -ß، -z</b> در برترین یک e می‌گیرند (am ältesten). ۳) صفت‌های پایان‌یافته به <b>‎-er، -el</b> آن e را در برتر می‌اندازند (teuer→teurer).'}},
  {type:'contrast',cols:[
   {t:'als — things are unequal',md:{en:'„Anna ist größer <b>als</b> Tom.“<br>„Der Zug ist schneller <b>als</b> das Auto.“<br>„Ich trinke lieber Tee <b>als</b> Kaffee.“<br>Always with a comparative form. <b>als</b> = „than“.'}},
   {t:'wie — things are equal',md:{en:'„Anna ist <b>so</b> groß <b>wie</b> Tom.“<br>„Er ist <b>genauso</b> alt <b>wie</b> ich.“<br>„Nicht <b>so</b> teuer <b>wie</b> gedacht.“<br>Always with the plain adjective and <b>so</b>. <b>wie</b> = „as“.'}}]},
  {type:'rule',md:{en:'The superlative comes in two shapes, and the difference is purely grammatical:<br>• <b>Before a noun</b> it is an adjective and takes adjective endings: „der <b>schnellste</b> Zug“, „die <b>beste</b> Pizza der Stadt“, „mit dem <b>schnellsten</b> Zug“.<br>• <b>Standing alone</b>, after sein/werden or with a verb, use <b>am …-sten</b>: „Dieser Zug ist <b>am schnellsten</b>.“ „Im Januar ist es <b>am kältesten</b>.“ „Ich arbeite morgens <b>am besten</b>.“<br>So: noun follows → der/die/das form; no noun → am-form.',
        fa:'برترین دو شکل دارد و تفاوت صرفاً دستوری است: <b>پیش از اسم</b> صفت است و پایانهٔ صفت می‌گیرد («der <b>schnellste</b> Zug»، «mit dem <b>schnellsten</b> Zug»). <b>تنها و بی‌اسم</b>، پس از sein/werden یا با فعل، شکل <b>am …-sten</b> را بگیر («Dieser Zug ist <b>am schnellsten</b>»).'}},
  {type:'examples',items:[
   {de:'Der Zug ist schneller als das Auto.',en:'The train is faster than the car.',say:'Der Zug ist schneller als das Auto.'},
   {de:'Mein Bruder ist genauso alt wie ich.',en:'My brother is exactly as old as I am.',say:'Mein Bruder ist genauso alt wie ich.'},
   {de:'Das ist der beste Kaffee in der Stadt.',en:'That is the best coffee in town.',say:'Das ist der beste Kaffee in der Stadt.'},
   {de:'Im Januar ist es hier am kältesten.',en:'It is coldest here in January.',say:'Im Januar ist es hier am kältesten.'},
   {de:'Ich trinke lieber Tee als Kaffee.',en:'I prefer tea to coffee.',say:'Ich trinke lieber Tee als Kaffee.'},
   {de:'Diese Wohnung ist viel teurer als die andere.',en:'This flat is much more expensive than the other one.',say:'Diese Wohnung ist viel teurer als die andere.'}]},
  {type:'warn',md:{en:'Three errors, and the first is unmistakably English:<br>1. „<s>mehr schnell</s>“ ✗ · „<s>mehr interessant</s>“ ✗ · „<s>mehr teuer</s>“ ✗ → <b>schneller, interessanter, teurer</b>. <b>mehr</b> exists only as the comparative of <i>viel</i>: „mehr Zeit“, „mehr Geld“. It is never a helper for another adjective.<br>2. „<s>größer wie ich</s>“ ✗ → „größer <b>als</b> ich“ ✓. You will hear natives say „wie“ here, especially in the south — it is a well-known regionalism and it is marked wrong in exams. <b>Comparative → als. so + plain adjective → wie.</b><br>3. „<s>der schnellste ist dieser Zug</s>“ is fine, but „<s>Dieser Zug ist der schnellste als alle</s>“ ✗ — the superlative takes no „als“ at all. Say „Dieser Zug ist <b>am schnellsten</b>.“',
        fa:'سه خطا، و نخستین کاملاً انگلیسی است: ۱) «mehr schnell» ✗ → <b>schneller</b>. <b>mehr</b> فقط برترِ <i>viel</i> است («mehr Zeit») و هرگز کمکِ صفت دیگری نیست. ۲) «größer wie ich» ✗ → «größer <b>als</b> ich» ✓؛ برتر با <b>als</b> و «so + صفت ساده» با <b>wie</b>. ۳) برترین هیچ «als» نمی‌گیرد: «Dieser Zug ist <b>am schnellsten</b>».'}},
  {type:'tip',md:{en:'Two patterns worth having ready-made:<br>• <b>immer + comparative</b> = „more and more“: „Es wird <b>immer kälter</b>.“ „Die Mieten werden <b>immer teurer</b>.“<br>• <b>je … desto</b> = „the … the …“: „<b>Je</b> mehr ich lerne, <b>desto</b> besser verstehe ich.“ Note the word order — the <i>je</i>-half puts its verb at the end, and the <i>desto</i>-half puts the comparative first and the verb second.',
        fa:'دو الگوی آمادهٔ به‌کار: <b>immer + برتر</b> = «بیشتر و بیشتر» («Es wird <b>immer kälter</b>»). و <b>je … desto</b> = «هرچه … آن‌چه …» («<b>Je</b> mehr ich lerne, <b>desto</b> besser verstehe ich») — دقت کن که نیمهٔ <i>je</i> فعلش را آخر می‌برد.'}},
  {type:'quiz',q:{en:'„Mit dem Fahrrad bin ich ___ als mit dem Bus.“',fa:'«Mit dem Fahrrad bin ich ___ als mit dem Bus.»'},
   a:'schneller',o:['mehr schnell','am schnellsten','so schnell'],
   ex:{en:'German builds the comparative with <b>-er</b> on the adjective itself, and the <b>als</b> in the sentence proves a comparative is needed. „mehr schnell“ copies English; „am schnellsten“ is the superlative and cannot take <i>als</i>; „so schnell“ would need <i>wie</i>.',
       fa:'آلمانی برتر را با <b>‎-er</b> روی خود صفت می‌سازد و وجود <b>als</b> در جمله ثابت می‌کند که برتر لازم است. «mehr schnell» انگلیسی را کپی می‌کند؛ «am schnellsten» برترین است و als نمی‌گیرد؛ «so schnell» به wie نیاز دارد.'}}
 ]},

/* ============ 18 · konjunktiv ============ */
{id:'konjunktiv',ic:'🌙',lv:5,sk:'Verbs',
 title:{en:'Konjunktiv II',fa:'وجه شرطی (Konjunktiv II)'},
 sub:{en:'Polite, hypothetical, and not actually the case',fa:'مؤدبانه، فرضی، و در واقع غیرواقعی'},
 blocks:[
  {type:'text',md:{en:'The Konjunktiv II is the mood German uses for anything that is <b>not presented as fact</b>: an unreal condition, a wish, cautious advice, or — most usefully for daily life — a polite request. English does the same job with „would“, „could“ and „were“: <i>if I were rich</i>, <i>could you help me</i>, <i>I would like</i>.<br>German has two ways to build it: a <b>one-word form</b> (wäre, hätte, könnte, müsste, wüsste) for a small group of very common verbs, and <b>würde + Infinitiv</b> for everything else.',
        fa:'Konjunktiv II وجهی است که آلمانی برای هر چیزی به کار می‌برد که <b>به‌عنوان واقعیت عرضه نمی‌شود</b>: شرط غیرواقعی، آرزو، توصیهٔ محتاطانه، و — پرکاربردتر از همه در زندگی روزمره — درخواست مؤدبانه. انگلیسی همان کار را با «would»، «could» و «were» می‌کند. آلمانی دو راه ساختن دارد: <b>شکل یک‌واژه‌ای</b> (wäre، hätte، könnte، müsste، wüsste) برای گروهی کوچک از فعل‌های پرکاربرد، و <b>würde + مصدر</b> برای بقیه.'}},
  {type:'table',head:['verb','Konjunktiv II','meaning'],rows:[
   ['sein','*wäre','would be'],
   ['haben','*hätte','would have'],
   ['werden','*würde','would'],
   ['können','*könnte','could'],
   ['müssen','*müsste','would have to'],
   ['dürfen','*dürfte','would be allowed to'],
   ['sollen','*sollte','should'],
   ['mögen','*möchte','would like'],
   ['wissen','*wüsste','would know'],
   ['es gibt','*es gäbe','there would be']],
   cap:{en:'Learn these ten and you almost never need würde at all.',
        fa:'همین ده مورد را یاد بگیر و تقریباً هیچ‌وقت به würde نیاز نداری.'}},
  {type:'table',head:['','wäre','hätte','würde'],rows:[
   ['ich','*wäre','*hätte','*würde'],
   ['du','wärst','hättest','würdest'],
   ['er/sie/es','*wäre','*hätte','*würde'],
   ['wir','wären','hätten','würden'],
   ['ihr','wärt','hättet','würdet'],
   ['sie/Sie','wären','hätten','würden']],
   cap:{en:'Like the modals, ich and er/sie/es are identical. Every form has an Umlaut — that is the Konjunktiv signal.',
        fa:'مثل فعل‌های وجهی، ich و er/sie/es یکسان‌اند. هر شکلی اوملاوت دارد — نشانهٔ Konjunktiv همین است.'}},
  {type:'rule',md:{en:'Which of the two forms do you use?<br>• <b>sein, haben, werden, the modals, wissen</b> → always the one-word form. „Ich <b>hätte</b> Zeit“, „Das <b>wäre</b> schön“, „Ich <b>könnte</b> kommen“.<br>• <b>every other verb</b> → <b>würde + Infinitiv</b>. „Ich <b>würde</b> das nicht <b>machen</b>“, „Sie <b>würde</b> gern <b>mitkommen</b>“.<br>One-word forms do exist for other verbs (<i>ich käme, ich ginge, ich täte</i>) but outside literature they sound archaic — in speech and in exam writing, use <b>würde</b>.',
        fa:'کدام شکل را به کار ببری؟ <b>sein، haben، werden، فعل‌های وجهی، wissen</b> → همیشه شکل یک‌واژه‌ای. <b>هر فعل دیگری</b> → <b>würde + مصدر</b>. شکل یک‌واژه‌ای برای فعل‌های دیگر هم وجود دارد (ich käme، ich ginge) اما بیرون از ادبیات کهنه به گوش می‌رسد.'}},
  {type:'contrast',cols:[
   {t:'Indikativ — it might really happen',md:{en:'„<b>Wenn</b> ich morgen Zeit <b>habe</b>, <b>komme</b> ich vorbei.“<br>„Wenn es regnet, bleiben wir zu Hause.“<br>A real, open possibility. Plain present tense on both sides.'}},
   {t:'Konjunktiv II — it is not the case',md:{en:'„<b>Wenn</b> ich Zeit <b>hätte</b>, <b>würde</b> ich vorbeikommen.“<br>„Wenn ich reich wäre, würde ich weniger arbeiten.“<br>I do not have time; I am not rich. Konjunktiv on <b>both</b> halves.'}}]},
  {type:'examples',items:[
   {de:'Ich hätte gern einen Kaffee, bitte.',en:'I would like a coffee, please.',say:'Ich hätte gern einen Kaffee, bitte.'},
   {de:'Könnten Sie mir bitte helfen?',en:'Could you help me, please?',say:'Könnten Sie mir bitte helfen?'},
   {de:'Wenn ich mehr Zeit hätte, würde ich mehr lesen.',en:'If I had more time, I would read more.',say:'Wenn ich mehr Zeit hätte, würde ich mehr lesen.'},
   {de:'An deiner Stelle würde ich den Arzt fragen.',en:'In your position I would ask the doctor.',say:'An deiner Stelle würde ich den Arzt fragen.'},
   {de:'Es wäre schön, wenn du mitkommen könntest.',en:'It would be nice if you could come along.',say:'Es wäre schön, wenn du mitkommen könntest.'},
   {de:'Du solltest wirklich früher ins Bett gehen.',en:'You really should go to bed earlier.',say:'Du solltest wirklich früher ins Bett gehen.'}]},
  {type:'warn',md:{en:'Three traps, all worth fixing:<br>1. <b>Never würde + haben/sein.</b> „<s>Wenn ich Zeit würde haben</s>“ ✗ · „<s>Es würde schön sein</s>“ ✗ → „Wenn ich Zeit <b>hätte</b>“ ✓ · „Es <b>wäre</b> schön“ ✓. The same for the modals: not „<s>würde können</s>“ but <b>könnte</b>.<br>2. <b>Both halves must be unreal.</b> „<s>Wenn ich reich bin, würde ich reisen</s>“ ✗ mixes a real condition with an unreal result → „Wenn ich reich <b>wäre</b>, würde ich reisen.“ ✓<br>3. <b>„would“ is not always würde.</b> English „I would like“ is <b>ich möchte</b> or <b>ich hätte gern</b>, never „<s>ich würde mögen</s>“ ✗. And a past habit — „when I was a child I would always…“ — is not Konjunktiv at all; that is just the past tense: „Als Kind <b>bin</b> ich immer … <b>gegangen</b>.“',
        fa:'سه دام: ۱) <b>هرگز würde + haben/sein</b> نگو: «Es würde schön sein» ✗ → «Es <b>wäre</b> schön» ✓؛ همین برای فعل‌های وجهی: <b>könnte</b>، نه «würde können». ۲) <b>هر دو نیمه باید غیرواقعی باشند</b>: «Wenn ich reich bin, würde ich reisen» ✗ → «Wenn ich reich <b>wäre</b>…» ✓. ۳) «would» انگلیسی همیشه würde نیست: «I would like» می‌شود <b>ich möchte</b> یا <b>ich hätte gern</b>.'}},
  {type:'tip',md:{en:'This is the fastest politeness upgrade in the language. Swap each form on the left for the one on the right and you instantly sound like a considerate adult rather than a demanding tourist:<br>Ich will → <b>Ich möchte / Ich hätte gern</b><br>Kannst du → <b>Könntest du</b> · Können Sie → <b>Könnten Sie</b><br>Hast du → <b>Hättest du</b> · Ist es möglich → <b>Wäre es möglich</b><br>Du musst → <b>Du solltest</b> (advice instead of an order)',
        fa:'سریع‌ترین ارتقای ادب در این زبان همین است. هر شکل چپ را با راست عوض کن: Ich will → <b>Ich möchte / Ich hätte gern</b>؛ Kannst du → <b>Könntest du</b>؛ Können Sie → <b>Könnten Sie</b>؛ Ist es möglich → <b>Wäre es möglich</b>؛ Du musst → <b>Du solltest</b>.'}},
  {type:'quiz',q:{en:'„Wenn ich mehr Zeit ___, würde ich Spanisch lernen.“',fa:'«Wenn ich mehr Zeit ___, würde ich Spanisch lernen.»'},
   a:'hätte',o:['habe','würde haben','hatte'],
   ex:{en:'The result half („würde … lernen“) is unreal, so the condition must be unreal too → <b>hätte</b>. „habe“ is the real Indikativ, „hatte“ is the ordinary past, and „würde haben“ breaks the rule that haben and sein always use their own one-word form.',
       fa:'نیمهٔ نتیجه («würde … lernen») غیرواقعی است، پس شرط هم باید غیرواقعی باشد → <b>hätte</b>. «habe» اخباری واقعی است، «hatte» گذشتهٔ ساده، و «würde haben» قاعده‌ای را می‌شکند که haben و sein همیشه شکل یک‌واژه‌ای خود را می‌گیرند.'}}
 ]},

/* ============ 19 · passiv ============ */
{id:'passiv',ic:'🔄',lv:5,sk:'Verbs',
 title:{en:'The passive voice',fa:'وجه مجهول'},
 sub:{en:'werden + Partizip — and why „Ich werde geholfen“ is wrong',fa:'werden + اسم مفعول — و چرا «Ich werde geholfen» غلط است'},
 blocks:[
  {type:'text',md:{en:'The passive moves the spotlight off the doer and onto the <b>action and its target</b>. You use it when the doer is unknown, irrelevant, or deliberately left out — which is why it is everywhere in official German: notices, instructions, reports, news.<br>The build is mechanical: <b>werden</b> takes the normal verb slot and gets conjugated; the <b>Partizip II</b> goes to the end. Think of <i>werden</i> as the engine and the participle as the cargo: the engine changes gear for tense and person, the cargo never changes at all.',
        fa:'مجهول نورافکن را از کنندهٔ کار برمی‌دارد و روی <b>عمل و هدفش</b> می‌اندازد. وقتی به‌کار می‌آید که کنندهٔ کار ناشناخته، بی‌اهمیت یا عمداً حذف‌شده باشد — و همین است که در آلمانیِ اداری فراوان است: اطلاعیه، دستورالعمل، گزارش، خبر. ساختش مکانیکی است: <b>werden</b> جایگاه عادی فعل را می‌گیرد و صرف می‌شود؛ <b>اسم مفعول</b> به آخر می‌رود.'}},
  {type:'table',head:['Tense','Form','Example'],rows:[
   ['Präsens','*wird + Partizip','Das Haus *wird gebaut.'],
   ['Präteritum','*wurde + Partizip','Das Haus *wurde 1920 gebaut.'],
   ['Perfekt','*ist + Partizip + worden','Das Haus *ist gebaut worden.'],
   ['Plusquamperfekt','*war + Partizip + worden','Das Haus *war gebaut worden.'],
   ['Futur','*wird + Partizip + werden','Das Haus *wird gebaut werden.'],
   ['with a modal','modal + Partizip + *werden','Das Haus *muss gebaut werden.'],
   ['Zustandspassiv','*ist + Partizip','Das Haus *ist gebaut. (= it stands finished)']],
   cap:{en:'In the Perfekt the participle of werden is worden, not geworden. That single word is the giveaway.',
        fa:'در ماضی نقلی، اسم مفعول werden می‌شود worden، نه geworden. همین یک واژه نشانهٔ کار است.'}},
  {type:'steps',items:[
   {en:'Find the <b>Akkusativ object</b> of the active sentence. „Der Chef schreibt <b>den Brief</b>.“',fa:'<b>مفعول آکوزاتیو</b> جملهٔ معلوم را پیدا کن: «Der Chef schreibt <b>den Brief</b>.»'},
   {en:'Make it the <b>subject</b> (Nominativ) of the passive sentence: „<b>Der Brief</b> …“',fa:'آن را <b>فاعل</b> (نومیناتیو) جملهٔ مجهول کن: «<b>Der Brief</b> …»'},
   {en:'Put <b>werden</b> in position 2, conjugated to match the new subject, and the Partizip II at the end: „Der Brief <b>wird geschrieben</b>.“',fa:'<b>werden</b> را در جایگاه ۲ بگذار، هم‌خوان با فاعل تازه، و اسم مفعول را در آخر: «Der Brief <b>wird geschrieben</b>.»'},
   {en:'Only if the doer matters, add it: a person with <b>von + Dativ</b> („von dem Chef“), a cause or means with <b>durch + Akkusativ</b> („durch ein Erdbeben“).',fa:'فقط اگر کنندهٔ کار مهم است، بیفزا: شخص با <b>von + داتیو</b>، و علت یا وسیله با <b>durch + آکوزاتیو</b>.'},
   {en:'No Akkusativ object in the active sentence? Then there is no normal passive — see the warning below.',fa:'جملهٔ معلوم مفعول آکوزاتیو ندارد؟ پس مجهول معمولی هم ندارد — به هشدار پایین نگاه کن.'}]},
  {type:'contrast',cols:[
   {t:'Vorgangspassiv — werden',md:{en:'An action <i>in progress</i>:<br>„Das Fenster <b>wird</b> geöffnet.“ — someone is opening it right now.<br>„Die Straße <b>wird</b> repariert.“ — work is going on.<br>This is the passive proper.'}},
   {t:'Zustandspassiv — sein',md:{en:'The <i>resulting state</i>:<br>„Das Fenster <b>ist</b> geöffnet.“ — it stands open.<br>„Die Straße <b>ist</b> repariert.“ — the work is finished.<br>Same participle, completely different claim. Mixing these up is a genuine meaning error, not a style slip.'}}]},
  {type:'examples',items:[
   {de:'Das Formular muss bis Freitag abgegeben werden.',en:'The form has to be handed in by Friday.',say:'Das Formular muss bis Freitag abgegeben werden.'},
   {de:'Der Brief wurde von meiner Chefin geschrieben.',en:'The letter was written by my boss. (von + Dativ)',say:'Der Brief wurde von meiner Chefin geschrieben.'},
   {de:'Die Rechnung ist schon bezahlt worden.',en:'The bill has already been paid.',say:'Die Rechnung ist schon bezahlt worden.'},
   {de:'Hier darf nicht geraucht werden.',en:'Smoking is not permitted here.',say:'Hier darf nicht geraucht werden.'},
   {de:'Mir wurde gesagt, dass der Zug Verspätung hat.',en:'I was told that the train is delayed.',say:'Mir wurde gesagt, dass der Zug Verspätung hat.'},
   {de:'Die Stadt wurde durch ein Erdbeben zerstört.',en:'The city was destroyed by an earthquake. (durch + Akkusativ)',say:'Die Stadt wurde durch ein Erdbeben zerstört.'}]},
  {type:'warn',md:{en:'The famous one: <b>Dative verbs have no personal passive.</b> English turns „someone helps me“ into „I am helped“, so you reach for the same move — and German refuses it, because <i>helfen</i> never had an Accusative object to promote.<br>„<s>Ich werde geholfen.</s>“ ✗ → „<b>Mir</b> wird geholfen.“ ✓ (or „<b>Es</b> wird mir geholfen.“)<br>The dative object stays stubbornly dative and the sentence simply has no real subject. Same with <b>danken, gratulieren, antworten, zuhören, vertrauen</b>:<br>„<s>Ich wurde gratuliert</s>“ ✗ → „<b>Mir</b> wurde gratuliert.“ ✓<br>Second trap: the Perfekt passive uses <b>worden</b>. „<s>Das Haus ist gebaut geworden</s>“ ✗ → „Das Haus ist gebaut <b>worden</b>.“ ✓ („geworden“ belongs to <i>werden</i> meaning „to become“: „Er ist Arzt geworden.“)',
        fa:'دام معروف: <b>فعل‌های داتیوی مجهولِ شخصی ندارند.</b> انگلیسی «someone helps me» را به «I am helped» تبدیل می‌کند و تو همان حرکت را می‌زنی — اما آلمانی نمی‌پذیرد، چون <i>helfen</i> هرگز مفعول آکوزاتیو نداشته تا ارتقا یابد. «Ich werde geholfen» ✗ → «<b>Mir</b> wird geholfen» ✓. همین برای danken، gratulieren، antworten و zuhören. دام دوم: مجهولِ ماضی نقلی <b>worden</b> می‌گیرد، نه geworden.'}},
  {type:'tip',md:{en:'Germans often dodge the passive altogether, and these alternatives sound more natural in speech:<br>• <b>man</b> + active: „<b>Man</b> spricht hier Deutsch.“ = German is spoken here.<br>• <b>sich lassen</b>: „Das <b>lässt sich</b> reparieren.“ = that can be repaired.<br>• <b>sein + zu + Infinitiv</b>: „Das Formular <b>ist</b> bis Freitag <b>abzugeben</b>.“ = the form is to be handed in.<br>• A plain active with a vague subject: „Sie bauen hier eine neue Schule.“<br>If a passive sentence feels heavy, one of these four will carry it better.',
        fa:'آلمانی‌زبان‌ها غالباً از مجهول می‌گریزند و این جانشین‌ها در گفتار طبیعی‌ترند: <b>man</b> + معلوم («Man spricht hier Deutsch»)؛ <b>sich lassen</b> («Das lässt sich reparieren»)؛ <b>sein + zu + مصدر</b> («Das Formular ist bis Freitag abzugeben»)؛ یا جملهٔ معلوم با فاعل مبهم.'}},
  {type:'quiz',q:{en:'„Die Rechnung ist schon bezahlt ___.“',fa:'«Die Rechnung ist schon bezahlt ___.»'},
   a:'worden',o:['geworden','gewesen','werden'],
   ex:{en:'This is the Perfekt passive, and there <b>werden</b> has the special participle <b>worden</b>. „geworden“ is the participle of the <i>other</i> werden („to become“: er ist Arzt geworden); „werden“ as an infinitive would belong after a modal („muss bezahlt werden“).',
       fa:'این مجهولِ ماضی نقلی است و در آن <b>werden</b> اسم مفعول ویژهٔ <b>worden</b> را می‌گیرد. «geworden» اسم مفعولِ werden به معنای «شدن» است؛ و «werden» مصدر، پس از فعل وجهی می‌آید («muss bezahlt werden»).'}}
 ]},

/* ============ 20 · nebensatz ============ */
{id:'nebensatz',ic:'🔗',lv:5,sk:'Sentences',
 title:{en:'Subordinate clauses',fa:'جمله‌های پیرو'},
 sub:{en:'weil, dass, wenn, obwohl — and the verb at the very end',fa:'weil، dass، wenn، obwohl — و فعل در آخرِ آخر'},
 blocks:[
  {type:'text',md:{en:'A subordinate clause is not a sentence standing next to another sentence — it is a <b>part</b> of one sentence, like a long adverb. German signals this structurally: the conjunction takes the slot that a verb would otherwise claim, so the conjugated verb is pushed all the way to the <b>end</b> of its clause. That verb-at-the-end is not an arbitrary rule; it is the audible marker that says „this chunk is subordinate“. Once you hear it that way, you can parse long German sentences by ear.',
        fa:'جملهٔ پیرو جمله‌ای نیست که کنار جملهٔ دیگری ایستاده باشد — <b>بخشی</b> از یک جمله است، مثل یک قید بلند. آلمانی این را ساختاری نشان می‌دهد: حرف ربط جایگاهی را می‌گیرد که فعل می‌خواست، پس فعل صرف‌شده تا <b>آخر</b> جملهٔ خود رانده می‌شود. فعل‌در‌آخر قاعده‌ای دلبخواهی نیست؛ نشانهٔ شنیداری «این تکه پیرو است» است.'}},
  {type:'table',head:['Conjunction','Meaning','Example'],rows:[
   ['*weil','because','Ich bleibe zu Hause, weil ich krank *bin.'],
   ['*dass','that','Ich glaube, dass er recht *hat.'],
   ['*wenn','if / whenever','Wenn es regnet, bleiben wir *hier.'],
   ['*als','when (one past event)','Als ich klein war, *wohnten wir dort.'],
   ['*obwohl','although','Er kam, obwohl er müde *war.'],
   ['*ob','whether','Ich weiß nicht, ob sie *kommt.'],
   ['*damit','so that','Ich schreibe es auf, damit du es nicht *vergisst.'],
   ['*bevor','before','Ruf mich an, bevor du *losfährst.'],
   ['*nachdem','after','Nachdem wir gegessen *hatten, gingen wir.'],
   ['*während','while','Während ich koche, deckt er den Tisch.']],
   cap:{en:'All ten push the conjugated verb to the end. Learning them is learning one pattern ten times.',
        fa:'همهٔ این ده مورد فعل صرف‌شده را به آخر می‌برند. یادگیری‌شان یعنی یادگیری یک الگو، ده بار.'}},
  {type:'rule',md:{en:'What happens at the end when there are <b>two</b> verbs? The <b>conjugated</b> one goes last, behind the infinitive or participle — the reverse of the main-clause order:<br>main: „Ich <b>muss</b> noch <b>arbeiten</b>.“ → sub: „…, weil ich noch <b>arbeiten muss</b>.“<br>main: „Ich <b>bin</b> zu spät <b>gekommen</b>.“ → sub: „…, weil ich zu spät <b>gekommen bin</b>.“<br>And separable verbs <b>rejoin</b>, because the prefix is already at the end: „Ich stehe früh <b>auf</b>“ → „…, weil ich früh <b>aufstehe</b>.“',
        fa:'وقتی <b>دو</b> فعل هست، در آخر چه می‌شود؟ فعل <b>صرف‌شده</b> آخرین می‌آید، پشت مصدر یا اسم مفعول — عکس ترتیب جملهٔ اصلی: «Ich muss noch arbeiten» → «…, weil ich noch <b>arbeiten muss</b>». و فعل‌های جداشدنی دوباره <b>می‌چسبند</b>، چون پیشوند از قبل در آخر است: «…, weil ich früh <b>aufstehe</b>».'}},
  {type:'contrast',cols:[
   {t:'Subordinating — verb last',md:{en:'<b>weil, dass, wenn, als, obwohl, ob, damit, bevor, nachdem, während, da, falls, seitdem, bis, solange</b><br>„Ich komme später, <b>weil</b> ich noch arbeiten <b>muss</b>.“<br>One sentence, comma, verb at the end.'}},
   {t:'Coordinating — nothing changes',md:{en:'<b>und, aber, oder, denn, sondern</b><br>„Ich komme später, <b>denn</b> ich <b>muss</b> noch arbeiten.“<br>These glue two main clauses together and leave the word order completely alone. <b>denn</b> means the same as <b>weil</b> but behaves oppositely.'}}]},
  {type:'steps',items:[
   {en:'Write the main clause normally, with the verb in position 2.',fa:'جملهٔ اصلی را عادی بنویس، با فعل در جایگاه ۲.'},
   {en:'Put a <b>comma</b>. In German the comma before a subordinate clause is compulsory, not stylistic.',fa:'یک <b>ویرگول</b> بگذار. در آلمانی ویرگول پیش از جملهٔ پیرو الزامی است، نه سلیقه‌ای.'},
   {en:'Write the conjunction, then the subject, then everything else — objects, adverbs, negation.',fa:'حرف ربط را بنویس، بعد فاعل، بعد بقیهٔ اجزا — مفعول، قید، نفی.'},
   {en:'Put the conjugated verb <b>last</b>. If there is a second verb, it stands just before it.',fa:'فعل صرف‌شده را <b>آخر</b> بگذار. اگر فعل دومی هست، درست پیش از آن می‌ایستد.'},
   {en:'If you move the subordinate clause to the front, it fills position 1 — so the main verb comes <b>straight after the comma</b>: „Weil ich krank bin, <b>bleibe</b> ich zu Hause.“',fa:'اگر جملهٔ پیرو را جلو بیاوری، جایگاه ۱ را پر می‌کند — پس فعل اصلی <b>بلافاصله پس از ویرگول</b> می‌آید: «Weil ich krank bin, <b>bleibe</b> ich zu Hause.»'}]},
  {type:'examples',items:[
   {de:'Ich bleibe heute zu Hause, weil ich krank bin.',en:'I am staying home today because I am ill.',say:'Ich bleibe heute zu Hause, weil ich krank bin.'},
   {de:'Ich glaube, dass du recht hast.',en:'I think that you are right.',say:'Ich glaube, dass du recht hast.'},
   {de:'Ich komme später, weil ich noch arbeiten muss.',en:'I will come later because I still have to work.',say:'Ich komme später, weil ich noch arbeiten muss.'},
   {de:'Weil es stark geregnet hat, sind wir zu Hause geblieben.',en:'Because it rained hard, we stayed at home.',say:'Weil es stark geregnet hat, sind wir zu Hause geblieben.'},
   {de:'Ich weiß nicht, ob sie heute noch kommt.',en:'I do not know whether she is still coming today.',say:'Ich weiß nicht, ob sie heute noch kommt.'},
   {de:'Ruf mich bitte an, bevor du losfährst.',en:'Please call me before you set off.',say:'Ruf mich bitte an, bevor du losfährst.'}]},
  {type:'warn',md:{en:'The habit to break is keeping English order after the conjunction:<br>„<s>Ich bleibe zu Hause, weil ich bin krank.</s>“ ✗ → „…, weil ich krank <b>bin</b>.“ ✓<br>„<s>Ich glaube, dass er hat recht.</s>“ ✗ → „…, dass er recht <b>hat</b>.“ ✓<br>You <i>will</i> hear native speakers say „weil ich bin krank“ in casual speech — it is a known spoken variant and it is marked wrong in every exam. Do not copy it.<br>Second trap: when the clause comes first, the result looks impossible to an English eye — <b>verb, comma, verb</b>: „Weil ich krank <b>bin</b>, <b>bleibe</b> ich zu Hause.“ That is correct. Nothing goes between the comma and the main verb, so „<s>Weil ich krank bin, ich bleibe zu Hause</s>“ ✗ is wrong.<br>Third: <b>denn</b> is not <b>weil</b>. „<s>Ich bleibe zu Hause, weil ich bin müde</s>“ ✗ — if you want that word order, the word is <b>denn</b>: „…, <b>denn</b> ich bin müde.“ ✓',
        fa:'عادتی که باید بشکنی، نگه‌داشتن ترتیب انگلیسی پس از حرف ربط است: «…, weil ich bin krank» ✗ → «…, weil ich krank <b>bin</b>» ✓. در گفتار خودمانی از آلمانی‌زبان‌ها «weil ich bin krank» را <i>خواهی</i> شنید؛ گونهٔ گفتاری شناخته‌شده‌ای است و در هر آزمونی غلط شمرده می‌شود. دام دوم: وقتی جملهٔ پیرو جلو بیاید، نتیجه برای چشم انگلیسی ناممکن به نظر می‌رسد — <b>فعل، ویرگول، فعل</b>: «Weil ich krank bin, <b>bleibe</b> ich zu Hause.» و همین درست است. سوم: <b>denn</b> همان <b>weil</b> نیست؛ اگر آن ترتیب را می‌خواهی، واژه <b>denn</b> است.'}},
  {type:'tip',md:{en:'<b>dass</b> or <b>das</b>? They sound identical and the test is quick. <b>dass</b> with two s is the conjunction „that“ and always introduces a clause with the verb at the end: „Ich hoffe, <b>dass</b> es klappt.“ <b>das</b> with one s is an article or a relative pronoun, and you can usually swap it for <i>welches</i> or point at something with it: „<b>das</b> Buch, <b>das</b> ich lese“. If you can delete it and the sentence still has a noun missing, it is <b>das</b>.',
        fa:'<b>dass</b> یا <b>das</b>؟ هم‌صدا هستند و آزمون سریع است. <b>dass</b> با دو s حرف ربط «که» است و همیشه جمله‌ای با فعلِ آخر می‌آورد. <b>das</b> با یک s حرف تعریف یا ضمیر موصولی است و معمولاً می‌توان آن را با <i>welches</i> عوض کرد: «das Buch, das ich lese».'}},
  {type:'quiz',q:{en:'Which continuation is correct? „Ich komme später, …“',fa:'کدام ادامه درست است؟ «Ich komme später, …»'},
   a:'weil ich noch arbeiten muss.',o:['weil ich muss noch arbeiten.','weil ich noch muss arbeiten.','weil muss ich noch arbeiten.'],
   ex:{en:'<b>weil</b> sends the conjugated verb to the end, and with two verbs the conjugated one goes <i>last of all</i>: „… noch <b>arbeiten muss</b>.“ The first wrong option keeps main-clause order (that order needs <b>denn</b>), and the third inverts as if it were a question.',
       fa:'<b>weil</b> فعل صرف‌شده را به آخر می‌فرستد، و با دو فعل، فعل صرف‌شده <i>آخرینِ همه</i> است: «… noch <b>arbeiten muss</b>». گزینهٔ نخست ترتیب جملهٔ اصلی را نگه داشته (آن ترتیب به <b>denn</b> نیاز دارد).'}}
 ]}

];
